data <- read_excel("long_incidence_dataset_prepared_corrected_new.xlsx", sheet = 1)



data <- data %>%
  group_by(ID) %>%
  arrange(ID, Visits, Date_corrected) %>%
  mutate(
    Study_entry2 = min(Date_corrected),  # First visit
    Study_exit2 = max(Date_corrected),   # Last visit
    visit_seq = row_number(),
    total_visits = n(),
    time_from_entry = as.numeric(Date_corrected - Study_entry2, units = "days"),
    total_FUP = as.numeric(Study_exit2 - Study_entry2, units = "days")
  ) %>%
  ungroup()






###DATA cleaning#######

# Check for any problematic follow-up times
problematic <- data %>%
  filter(total_FUP <= 0) %>%
  distinct(ID, Study_entry2, Study_exit2, total_FUP)



nrow(problematic)  # Should be 0 if all follow-up times are valid



problematic_check <- data %>%
  filter(total_FUP <= 0) %>%
  group_by(ID) %>%
  summarise(
    Study_entry2 = first(Study_entry2),
    Study_exit2 = first(Study_exit2),
    total_FUP = first(total_FUP),
    n_rows = n(),
    min_date = min(Date_corrected),
    max_date = max(Date_corrected),
    .groups = 'drop'
  )

print(problematic_check)


ids_to_remove <- problematic_check$ID

data <- data %>%
  filter(!ID %in% ids_to_remove)



