# ------------------------------------------------------------
# 2. FUNCTION TO RECODE VARIABLES
# ------------------------------------------------------------

recode_variables <- function(dat) {
  
  # ==========================================================
  # A. RECODE manuscript_su_last_inj_new
  # ==========================================================
  
  dat <- dat %>%
    mutate(
      manuscript_su_last_inj_new2 = case_when(
        
        manuscript_su_last_inj_new == "No injection in last 3 months" |
          manuscript_su_last_inj_new == "No, used new syringe"
        ~ "No",
        
        manuscript_su_last_inj_new ==
          "Yes, re-used own syringe"
        ~ "Yes, re-used own syringe",
        
        manuscript_su_last_inj_new ==
          "Yes, re-used someone else’s syringe"
        ~ "Yes, re-used someone else’s syringe"
      )
    )
  
  dat$manuscript_su_last_inj_new2 <- factor(
    dat$manuscript_su_last_inj_new2,
    levels = c(
      "No",
      "Yes, re-used own syringe",
      "Yes, re-used someone else’s syringe"
    )
  )
  
  # ==========================================================
  # B. RECODE manuscript_MaritalStatus
  # ==========================================================
  
  dat <- dat %>%
    mutate(
      manuscript_MaritalStatus2 = case_when(
        
        manuscript_MaritalStatus == "Married"
        ~ "Married",
        
        manuscript_MaritalStatus == "Unmarried"
        ~ "Unmarried",
        
        manuscript_MaritalStatus %in%
          c("Separated", "Divorced", "Widowed")
        ~ "Divorced/Separated/Widowed"
      )
    )
  
  dat$manuscript_MaritalStatus2 <- factor(
    dat$manuscript_MaritalStatus2,
    levels = c(
      "Unmarried",
      "Married",
      "Divorced/Separated/Widowed"
    )
  )
  
  return(dat)
}

# ------------------------------------------------------------
# 3. APPLY TO ALL 20 IMPUTED DATASETS
# ------------------------------------------------------------

completed_list_recoded <- lapply(
  completed_list,
  recode_variables
)

# ------------------------------------------------------------
# 4. APPLY SAME RECODING TO ORIGINAL INCOMPLETE DATA
# ------------------------------------------------------------

orig_data_recoded <- recode_variables(orig_data)

# ------------------------------------------------------------
# 5. REBUILD mids OBJECT
# ------------------------------------------------------------

imp_ml_recoded <- as.mids(
  bind_rows(
    list(orig_data_recoded),
    completed_list_recoded,
    .id = ".imp"
  ) %>%
    mutate(
      .imp = as.integer(.imp) - 1,
      .id = row_number()
    )
)

