# COMPLETELY FIXED MNAR SENSITIVITY ANALYSIS


library(mice)
library(dplyr)
library(survival)
library(ggplot2)


# STEP 1: Get original missingness pattern


# Get original data to know which rows were missing
orig_data <- mice::complete(imp_ml, action = 0)
orig_missing <- is.na(orig_data$manuscript_place_inject_new)


# STEP 2: Calculate IMOR under MAR
-

# Get long format of imputed data
imp_long <- mice::complete(imp_ml, action = "long", include = TRUE)

# Create binary exposure
imp_long <- imp_long %>%
  mutate(
    place_binary = ifelse(manuscript_place_inject_new == "Public spaces", 1, 0),
    incomp = 0
  )

# Map original missingness to all rows
for(i in unique(imp_long$.imp)) {
  if(i == 0) {
    imp_long$incomp[imp_long$.imp == 0] <- as.integer(orig_missing)
  } else {
    imp_long$incomp[imp_long$.imp == i] <- as.integer(orig_missing)
  }
}

# Calculate IMOR
imor_list <- c()
for(i in unique(imp_long$.imp)) {
  if(i == 0) next
  temp <- imp_long %>% dplyr::filter(.imp == i)
  if(length(unique(temp$place_binary)) >= 2 & length(unique(temp$incomp)) >= 2) {
    fit <- glm(place_binary ~ incomp, family = binomial, data = temp)
    imor_list <- c(imor_list, coef(fit)[2])
  }
}
mean_log_odds <- mean(imor_list, na.rm = TRUE)
IMOR_MAR <- exp(mean_log_odds)


# STEP 3: Population prevalence under MAR


prev_by_imp <- numeric(imp_ml$m)
for(i in 1:imp_ml$m) {
  data_i <- mice::complete(imp_ml, i)
  prev_by_imp[i] <- mean(data_i$manuscript_place_inject_new == "Public spaces", na.rm = TRUE)
}
prev_MAR <- mean(prev_by_imp)


# STEP 4: Sensitivity analysis using delta adjustment


# Define delta range
delta_seq <- seq(-1.5, 1.5, by = 0.25)

# Initialize results
tipping <- data.frame(
  delta = delta_seq,
  HR = NA,
  CI_lower = NA,
  CI_upper = NA,
  IMOR = NA,
  prev_pop = NA
)

# For each delta value
###

for(j in seq_along(delta_seq)) {
  
  delta <- delta_seq[j]
  cat("\nProcessing delta =", delta, "(", j, "/", length(delta_seq), ")\n")
  
  # Store results from each imputation
  coefs <- numeric(imp_ml$m)
  se_coefs <- numeric(imp_ml$m)
  exposure_prev <- numeric(imp_ml$m)
  
  for(i in 1:imp_ml$m) {
    
    # Get imputed dataset
    data_i <- mice::complete(imp_ml, i)
    
    # Create binary exposure (1 = Public spaces, 0 = Home or indoor)
    exposure_original <- as.numeric(data_i$manuscript_place_inject_new == "Public spaces")
    
    # Start with original exposure values
    exposure_adjusted <- exposure_original
    
    if(any(orig_missing)) {
      # Calculate baseline log-odds among observed (with smoothing)
      observed_exposure <- exposure_original[!orig_missing]
      baseline_prob <- mean(observed_exposure, na.rm = TRUE)
      # Add small value to avoid log(0) or log(1)
      baseline_prob <- pmin(pmax(baseline_prob, 0.001), 0.999)
      baseline_logit <- log(baseline_prob / (1 - baseline_prob))
      
      # Adjust log-odds for missing rows by adding delta
      adjusted_logit <- baseline_logit + delta
      adjusted_prob <- 1 / (1 + exp(-adjusted_logit))
      
      # Sample new exposure values for missing rows
      set.seed(123 + i * 100 + j * 10)
      exposure_adjusted[orig_missing] <- rbinom(sum(orig_missing), 1, adjusted_prob)
    }
    
    # Store prevalence for this imputation
    exposure_prev[i] <- mean(exposure_adjusted, na.rm = TRUE)
    
    # Add adjusted exposure to dataset
    data_i$exposure_mnar <- factor(exposure_adjusted, 
                                   levels = c(0, 1),
                                   labels = c("Home or indoor", "Public spaces"))
    
    # Fit Cox model - capture warnings but proceed
    fit <- tryCatch({
      coxph(Surv(START, STOP, LEAD_HIV) ~
              exposure_mnar +
              new_agegroup + Sex +
              manuscript_education_cat +
              manuscript_MaritalStatus +
              source_income +
              recent_homelessness +
              recent_incarceration +
              new_test_year +
              City_Name +
              duraion_injection_quartile +
              cluster(RegNo),
            data = data_i)
    }, warning = function(w) {
      # Still return the fit even with warnings
      return(suppressWarnings(coxph(Surv(START, STOP, LEAD_HIV) ~
                                      exposure_mnar +
                                      new_agegroup + Sex +
                                      manuscript_education_cat +
                                      manuscript_MaritalStatus +
                                      source_income +
                                      recent_homelessness +
                                      recent_incarceration +
                                      new_test_year +
                                      City_Name +
                                      duraion_injection_quartile +
                                      cluster(RegNo),
                                    data = data_i)))
    }, error = function(e) {
      cat("Error in imputation", i, ":", e$message, "\n")
      return(NULL)
    })
    
    if(!is.null(fit)) {
      # Extract coefficient for exposure_mnarPublic
      coef_sum <- summary(fit)
      coef_names <- rownames(coef_sum$coefficients)
      idx <- grep("exposure_mnarPublic", coef_names)
      
      if(length(idx) > 0) {
        coefs[i] <- coef_sum$coefficients[idx, 1]
        se_coefs[i] <- coef_sum$coefficients[idx, 3]  # se(coef)
      }
    }
  }
  
  # Pool results using Rubin's rules (manual pooling)
  valid_idx <- !is.na(coefs) & !is.na(se_coefs) & se_coefs > 0
  
  if(sum(valid_idx) > 0) {
    coefs_valid <- coefs[valid_idx]
    se_valid <- se_coefs[valid_idx]
    
    # Pooled estimate (average)
    pooled_coef <- mean(coefs_valid)
    
    # Within-imputation variance
    within_var <- mean(se_valid^2)
    
    # Between-imputation variance
    between_var <- var(coefs_valid)
    
    # Total variance (Rubin's rules)
    total_var <- within_var + between_var * (1 + 1/sum(valid_idx))
    pooled_se <- sqrt(total_var)
    
    # Store results
    tipping$HR[j] <- exp(pooled_coef)
    tipping$CI_lower[j] <- exp(pooled_coef - 1.96 * pooled_se)
    tipping$CI_upper[j] <- exp(pooled_coef + 1.96 * pooled_se)
    tipping$logHR[j] <- pooled_coef
    tipping$se_logHR[j] <- pooled_se
  }
  
  # Store IMOR and prevalence
  tipping$IMOR[j] <- exp(delta)
  tipping$prev_pop[j] <- mean(exposure_prev, na.rm = TRUE)
}


# STEP 5: Display results



print(tipping %>%
        select(delta, IMOR, prev_pop, HR, CI_lower, CI_upper) %>%
        mutate(across(where(is.numeric), ~ round(., 3))))


# STEP 6: Create plots (FIXED)















# Remove any rows with NA HR
tipping_clean <- tipping %>% filter(!is.na(HR) & !is.na(IMOR))
tipping_clean
# Plot 1: HR vs IMOR
p1 <- ggplot(tipping_clean, aes(x = IMOR, y = HR)) +
  geom_ribbon(aes(ymin = CI_lower, ymax = CI_upper), fill = "grey70", alpha = 0.4) +
  geom_line(size = 1.2, color = "steelblue") +
  geom_point(size = 2.5, color = "steelblue") +
  geom_hline(yintercept = 1, linetype = "dashed", color = "red", linewidth = 0.8) +
  # Add MAR reference point
  geom_point(data = tipping_clean[abs(tipping_clean$delta) < 0.01, , drop = FALSE],
             aes(x = IMOR_MAR, y = HR),
             color = "darkred", size = 4, shape = 18) +
  geom_vline(xintercept = IMOR_MAR, linetype = "dotted", color = "darkred", linewidth = 0.8) +
  scale_x_log10(breaks = c(0.25, 0.5, 0.75, 1, 1.5, 2, 3, 4),
                labels = c("0.25", "0.5", "0.75", "1", "1.5", "2", "3", "4")) +
  labs(
    x = "IMOR (Ignorable Missingness Odds Ratio)",
    y = "Hazard Ratio (Public vs Home injection)",
    title = "MNAR Sensitivity Analysis",
    subtitle = paste("Vertical line: IMOR under MAR assumption (", round(IMOR_MAR, 3), ")")
  ) +
  theme_minimal(base_size = 12) +
  theme(plot.title = element_text(hjust = 0.5, face = "bold"))

print(p1)

