# ============================================================
# MULTINOMIAL MNAR SENSITIVITY ANALYSIS
# For manuscript_su_last_inj_new (4 categories)
# ============================================================

library(mice)
library(dplyr)
library(survival)
library(ggplot2)
library(tidyr)
library(nnet)  # For multinomial models

# -------------------------------------------------------------------
# STEP 1: Understand the variable categories
# -------------------------------------------------------------------

# Check categories
categories <- c("No", 
                "Yes, re-used own syringe",
                "Yes, re-used someone else’s syringe" 
)

cat("Categories for manuscript_su_last_inj_new2:\n")
for(cat in categories) {
  cat("- ", cat, "\n")
}

# Get original missingness pattern
orig_data <- mice::complete(imp_ml, action = 0)
orig_missing <- is.na(orig_data$manuscript_su_last_inj_new2)
missing_prop <- mean(orig_missing)
cat("\nProportion missing:", round(missing_prop * 100, 1), "%\n")

# -------------------------------------------------------------------
# STEP 2: Calculate category-specific IMORs under MAR
# -------------------------------------------------------------------

# Get long format of imputed data
imp_long <- mice::complete(imp_ml, action = "long", include = TRUE)

# Create indicator variables for each category
imp_long <- imp_long %>%
  mutate(
    
    cat_no_injection = as.numeric(manuscript_su_last_inj_new2 == "No"),
    cat_own_syringe = as.numeric(manuscript_su_last_inj_new2 == "Yes, re-used own syringe"),
    cat_other_syringe = as.numeric(manuscript_su_last_inj_new2 == "Yes, re-used someone else’s syringe"),
    incomp = 0
  )

# Map original missingness to all rows
for(i in unique(imp_long$.imp)) {
  if(i == 0) {
    imp_long$incomp[imp_long$.imp == 0] <- as.integer(orig_missing)
  } else {
    imp_long$incomp[imp_long$.imp == i] <- as.integer(orig_missing)
  }
}
# Calculate IMOR for each category (using No re-syringe as reference)
categories_to_test <- c("cat_own_syringe", "cat_other_syringe")
imor_results <- list()
for(cat in categories_to_test) {
  imor_list <- c()
  for(i in unique(imp_long$.imp)) {
    if(i == 0) next
    temp <- imp_long %>% dplyr::filter(.imp == i)
    if(length(unique(temp[[cat]])) >= 2 & length(unique(temp$incomp)) >= 2) {
      fit <- glm(temp[[cat]] ~ incomp, family = binomial, data = temp)
      imor_list <- c(imor_list, coef(fit)[2])
    }
  }
  mean_log_odds <- mean(imor_list, na.rm = TRUE)
  imor_results[[cat]] <- data.frame(
    Category = gsub("cat_", "", cat),
    IMOR_MAR = exp(mean_log_odds),
    log_odds_MAR = mean_log_odds
  )
}
imor_df <- do.call(rbind, imor_results)


print(imor_df)

prop_by_imp <- matrix(NA, nrow = imp_ml$m, ncol = 3)
colnames(prop_by_imp) <- c("No", "Own syringe", "Other's syringe")
for(i in 1:imp_ml$m) {
  data_i <- mice::complete(imp_ml, i)
  prop_by_imp[i, 1] <- mean(data_i$manuscript_su_last_inj_new2 == "No", na.rm = TRUE)
  prop_by_imp[i, 2] <- mean(data_i$manuscript_su_last_inj_new2 == "Yes, re-used own syringe", na.rm = TRUE)
  prop_by_imp[i, 3] <- mean(data_i$manuscript_su_last_inj_new2 == "Yes, re-used someone else’s syringe", na.rm = TRUE)
}
prop_MAR <- colMeans(prop_by_imp)
names(prop_MAR) <- colnames(prop_by_imp)

print(round(prop_MAR, 2))

delta_seq <- seq(-1.5, 1.5, by = 0.5)

# Initialize results data frame BEFORE the loops (only once)
results_multinomial_updated <- data.frame()

for(delta_own in delta_seq) {
  for(delta_other in delta_seq) {
    
    cat("\nProcessing deltas - Own:", delta_own, 
        "| Other:", delta_other, "\n")
    
    # Store results from each imputation
    hr_own <- numeric(imp_ml$m)
    hr_other <- numeric(imp_ml$m)
    se_own <- numeric(imp_ml$m)
    se_other <- numeric(imp_ml$m)
    
    for(i in 1:imp_ml$m) {
      
      # Get imputed dataset
      data_i <- mice::complete(imp_ml, i)
      
      # Get observed proportions (only among non-missing)
      observed_data <- data_i[!orig_missing, ]
      prop_observed <- c(
        mean(observed_data$manuscript_su_last_inj_new2 == "No"),
        mean(observed_data$manuscript_su_last_inj_new2 == "Yes, re-used own syringe"),
        mean(observed_data$manuscript_su_last_inj_new2 == "Yes, re-used someone else’s syringe")
      )
      names(prop_observed) <- c("No", "Own", "Other")
      
      # Apply delta shifts to log-odds for missing rows
      if(any(orig_missing)) {
        
        # Start with observed proportions as baseline
        log_odds_ref <- log(prop_observed / prop_observed[1])  # Reference is "No injection in last three months"
        
        # Apply deltas
        log_odds_adj <- log_odds_ref
        log_odds_adj["Own"] <- log_odds_adj["Own"] + delta_own
        log_odds_adj["Other"] <- log_odds_adj["Other"] + delta_other
        
        # Convert to probabilities
        prob_adj <- exp(log_odds_adj) / (1 + sum(exp(log_odds_adj[-1])))
        prob_adj <- c(1 - sum(prob_adj[-1]), prob_adj[-1])
        names(prob_adj) <- names(prop_observed)
        
        # Ensure probabilities are valid
        prob_adj <- pmax(pmin(prob_adj, 0.999), 0.001)
        prob_adj <- prob_adj / sum(prob_adj)
        
        # Sample new categories for missing rows
        set.seed(123 + i * 100 + delta_own * 1000 + delta_other * 100)
        n_missing <- sum(orig_missing)
        sampled_cats <- sample(
          c(
            "No", 
            "Yes, re-used own syringe",
            "Yes, re-used someone else’s syringe"),
          size = n_missing,
          replace = TRUE,
          prob = prob_adj
        )
        
        # Update the dataset
        data_i$manuscript_su_last_inj_new2[orig_missing] <- sampled_cats
      }
      
      # Create dummy variables for Cox model
      data_i$inj_own <- as.numeric(data_i$manuscript_su_last_inj_new2 == "Yes, re-used own syringe")
      data_i$inj_other <- as.numeric(data_i$manuscript_su_last_inj_new2 == "Yes, re-used someone else’s syringe")
      # Reference: "No injection in last 3 months"
      
      # Fit Cox model
      fit <- tryCatch({
        coxph(Surv(START, STOP, LEAD_HIV) ~
                inj_own + inj_other + 
                new_agegroup + Sex +
                manuscript_education_cat +
                manuscript_MaritalStatus2 +
                source_income +
                recent_homelessness +
                recent_incarceration +
                new_test_year +
                City_Name +
                duraion_injection_quartile +
                cluster(RegNo),
              data = data_i)
      }, error = function(e) {
        cat("Error in imputation", i, ":", e$message, "\n")
        return(NULL)
      })
      
      if(!is.null(fit)) {
        coef_sum <- summary(fit)
        # Extract coefficients
        
        if("inj_own" %in% rownames(coef_sum$coefficients)) {
          hr_own[i] <- exp(coef_sum$coefficients["inj_own", 1])
          se_own[i] <- coef_sum$coefficients["inj_own", 3]
        }
        if("inj_other" %in% rownames(coef_sum$coefficients)) {
          hr_other[i] <- exp(coef_sum$coefficients["inj_other", 1])
          se_other[i] <- coef_sum$coefficients["inj_other", 3]
        }
      }
    }
    
    # Pool results (on log scale then exponentiate)
    
    valid_own <- !is.na(hr_own) & hr_own > 0 & !is.na(se_own)
    if(sum(valid_own) > 0) {
      log_hr_own <- log(hr_own[valid_own])
      pooled_hr_own <- exp(mean(log_hr_own))
      pooled_se_own <- sqrt(mean(se_own[valid_own]^2) + var(log_hr_own) * (1 + 1/sum(valid_own)))
    } else {
      pooled_hr_own <- NA
      pooled_se_own <- NA
    }
    
    valid_other <- !is.na(hr_other) & hr_other > 0 & !is.na(se_other)
    if(sum(valid_other) > 0) {
      log_hr_other <- log(hr_other[valid_other])
      pooled_hr_other <- exp(mean(log_hr_other))
      pooled_se_other <- sqrt(mean(se_other[valid_other]^2) + var(log_hr_other) * (1 + 1/sum(valid_other)))
    } else {
      pooled_hr_other <- NA
      pooled_se_other <- NA
    }
    
    # Create a single row data frame for current iteration
    current_row <- data.frame(
      delta_own = delta_own,
      delta_other = delta_other,
      IMOR_own = exp(delta_own),
      IMOR_other = exp(delta_other),
      HR_own = pooled_hr_own,
      HR_own_lower = ifelse(!is.na(pooled_hr_own) & !is.na(pooled_se_own), 
                            exp(log(pooled_hr_own) - 1.96 * pooled_se_own), NA),
      HR_own_upper = ifelse(!is.na(pooled_hr_own) & !is.na(pooled_se_own), 
                            exp(log(pooled_hr_own) + 1.96 * pooled_se_own), NA),
      HR_other = pooled_hr_other,
      HR_other_lower = ifelse(!is.na(pooled_hr_other) & !is.na(pooled_se_other), 
                              exp(log(pooled_hr_other) - 1.96 * pooled_se_other), NA),
      HR_other_upper = ifelse(!is.na(pooled_hr_other) & !is.na(pooled_se_other), 
                              exp(log(pooled_hr_other) + 1.96 * pooled_se_other), NA)
    )
    
    # Bind the current row to results
    results_multinomial_updated <- rbind(results_multinomial_updated, current_row)
  }
}


# Display results
print(results_multinomial_updated)


