pB <- ggplot(heatmap_data_syringe, aes(x = delta_other, y = delta_own, fill = HR_other)) +
  geom_tile() +
  geom_contour(aes(z = HR_other), color = "white", alpha = 0.6) +
  scale_fill_gradient2(
    low = "#2C7BB6",
    mid = "white",
    high = "#D7191C",
    midpoint = 1,
    name = "HR"
  ) + 
  # Mark the point where delta_other = 0 and delta_own = 0 (the MAR assumption)
  geom_point(data = subset(heatmap_data_syringe, delta_other == 0 & delta_own == 0),
             aes(x = delta_other, y = delta_own),
             shape = 21, fill = "black", size = 3) +
  
  labs(
    x = expression(delta[other]),
    y = expression(delta[own]),
    title = "B. Joint MNAR scenarios (key exposure)"
  ) +
  
  theme_minimal(base_size = 12) +
  theme(
    plot.title = element_text(face = "bold")
  )

