library(dplyr)
library(ggplot2)

main_effects_imor_syringe <- results_multinomial_updated %>%
  filter(
    (delta_other == 0 ) |
      (delta_own == 0 ) 
  ) %>%
  mutate(
    Category = case_when(
      delta_other == 0  ~ "Yes, re-used own syringe",
      delta_own == 0  ~ "Yes, re-used someone else’s syringe"
    ),
    
    # Map Δ → IMOR (this is the key change)
    IMOR = case_when(
      Category == "Yes, re-used own syringe" ~ exp(delta_own),
      Category == "Yes, re-used someone else’s syringe" ~ exp(delta_other)
    ),
    
    HR = case_when(
      Category == "Yes, re-used own syringe" ~ HR_own,
      Category == "Yes, re-used someone else’s syringe" ~ HR_other
    ),
    
    Lower = case_when(
      Category == "Yes, re-used own syringe" ~ HR_own_lower,
      Category == "Yes, re-used someone else’s syringe" ~ HR_other_lower
    ),
    
    Upper = case_when(
      Category == "Yes, re-used own syringe" ~ HR_own_upper,
      Category == "Yes, re-used someone else’s syringe" ~ HR_other_upper
    )
  ) %>%
  arrange(Category, IMOR)



pA_imor <- ggplot(main_effects_imor_syringe, aes(x = IMOR, y = HR)) +
  geom_ribbon(aes(ymin = Lower, ymax = Upper), fill = "grey85") +
  geom_line(size = 1.2, color = "black") +
  geom_hline(yintercept = 1, linetype = "dashed") +
  geom_vline(xintercept = 1, linetype = "dotted") +
  
  # Critical for interpretability
  scale_x_log10() +
  
  facet_wrap(~Category, scales = "free_y") +
  
  labs(
    x = "IMOR (departure from MAR; log scale)",
    y = "Hazard Ratio n(ref: No injection sharing)",
    title = ""
  ) +
  
  theme_minimal(base_size = 12) +
  theme(
    strip.text = element_text(face = "bold"),
    plot.title = element_text(face = "bold"),
    panel.grid.minor = element_blank()
  )

pA_imor





