# Calculate time between consecutive tests
follow_up_intervals <- data %>%
  group_by(ID) %>%
  arrange(Date_corrected, .by_group = TRUE) %>%
  mutate(
    visit_number = row_number(),  # 1, 2, 3...
    days_since_previous = as.numeric(Date_corrected - lag(Date_corrected)),
    # Fix: visit_number == 2 is the interval between visit 1 and visit 2
    # visit_number == 1 has no previous, so we label based on the CURRENT visit
    interval_type = case_when(
      visit_number == 2 ~ "baseline_to_first",  # Interval from visit 1 to visit 2
      visit_number > 2 ~ "subsequent"           # Later intervals
    )
  ) %>%
  ungroup() %>%
  filter(!is.na(days_since_previous))  # Remove the first visit (no previous)

# Check if you have data
print(paste("Total intervals:", nrow(follow_up_intervals)))
print(table(follow_up_intervals$interval_type, useNA = "ifany"))

# Now calculate statistics separately
# 1. Baseline to first test (Visit 1 to Visit 2)
baseline_to_first_stats <- follow_up_intervals %>%
  filter(interval_type == "baseline_to_first") %>%
  summarise(
    n = n(),
    mean_days = mean(days_since_previous, na.rm = TRUE),
    sd_days = sd(days_since_previous, na.rm = TRUE),
    median_days = median(days_since_previous, na.rm = TRUE),
    q25_days = quantile(days_since_previous, 0.25, na.rm = TRUE),
    q75_days = quantile(days_since_previous, 0.75, na.rm = TRUE),
    min_days = min(days_since_previous, na.rm = TRUE),
    max_days = max(days_since_previous, na.rm = TRUE)
  )

baseline_to_first_stats

# 2. Subsequent intervals (between Visit 2 and later)
