# Calculate time between consecutive tests using the variables you already have
follow_up_intervals <- data %>%
  group_by(ID) %>%
  arrange(Date_corrected, .by_group = TRUE) %>%
  mutate(
    days_since_previous = as.numeric(Date_corrected - lag(Date_corrected)),
    # Use Visits to identify intervals (0 to 1, 1 to 2, etc.)
    from_visit = lag(Visits),
    to_visit = Visits,
    # Categorize the interval type
    interval_type = case_when(
      from_visit == 0 & to_visit == 1 ~ "baseline_to_first",  # Visit 0 to Visit 1
      from_visit >= 1 & to_visit >= 2 ~ "subsequent"          # All later intervals
    )
  ) %>%
  ungroup() %>%
  filter(!is.na(days_since_previous))  # Remove first visit (no previous)

# Check distribution
print(table(follow_up_intervals$interval_type, useNA = "ifany"))

# 1. Baseline to first test (Visit 0 to Visit 1)
baseline_to_first_stats <- follow_up_intervals %>%
  filter(interval_type == "baseline_to_first") %>%
  summarise(
    n = n(),
    mean_days = mean(days_since_previous, na.rm = TRUE),
    sd_days = sd(days_since_previous, na.rm = TRUE),
    median_days = median(days_since_previous, na.rm = TRUE),
    q25_days = quantile(days_since_previous, 0.25, na.rm = TRUE),
    q75_days = quantile(days_since_previous, 0.75, na.rm = TRUE),
    min_days = min(days_since_previous, na.rm = TRUE),
    max_days = max(days_since_previous, na.rm = TRUE),
    # Also in years
    median_years = median_days / 365.25,
    q25_years = q25_days / 365.25,
    q75_years = q75_days / 365.25
  )

# 2. Subsequent intervals (Visit 1→2, 2→3, etc.)
subsequent_stats <- follow_up_intervals %>%
  filter(interval_type == "subsequent") %>%
  summarise(
    n = n(),
    mean_days = mean(days_since_previous, na.rm = TRUE),
    sd_days = sd(days_since_previous, na.rm = TRUE),
    median_days = median(days_since_previous, na.rm = TRUE),
    q25_days = quantile(days_since_previous, 0.25, na.rm = TRUE),
    q75_days = quantile(days_since_previous, 0.75, na.rm = TRUE),
    min_days = min(days_since_previous, na.rm = TRUE),
    max_days = max(days_since_previous, na.rm = TRUE),
    # Also in years
    median_years = median_days / 365.25,
    q25_years = q25_days / 365.25,
    q75_years = q75_days / 365.25
  )

# View results
print("Baseline to first test intervals (Visit 0 → Visit 1):")
print(baseline_to_first_stats)

print("Subsequent test intervals (Visit 1→2, 2→3, etc.):")
print(subsequent_stats)

