# 1. Basic count of tests per person
tests_per_person <- data %>%
  group_by(ID) %>%
  summarise(
    total_tests = n(),  # Total number of tests/visits per person
    baseline_visit = sum(Visits == 0, na.rm = TRUE),  # Should be 1 per person
    followup_visits = sum(Visits > 0, na.rm = TRUE)   # Number of follow-up visits
  ) %>%
  ungroup()

# 2. Statistics for total tests per person
tests_stats <- tests_per_person %>%
  summarise(
    # Overall counts
    n_persons = n(),
    total_tests_all = sum(total_tests),
    
    # Central tendency
    mean_tests = mean(total_tests, na.rm = TRUE),
    sd_tests = sd(total_tests, na.rm = TRUE),
    median_tests = median(total_tests, na.rm = TRUE),
    
    # Quartiles and IQR
    q25_tests = quantile(total_tests, 0.25, na.rm = TRUE),
    q75_tests = quantile(total_tests, 0.75, na.rm = TRUE),
    iqr_tests = IQR(total_tests, na.rm = TRUE),
    
    # Range
    min_tests = min(total_tests, na.rm = TRUE),
    max_tests = max(total_tests, na.rm = TRUE)
  )

tests_stats

