risk_table_Pak_dat2 <- incidence_rate_prepared %>%
  select(
    Year,
    Total_IDs,
    Events,
    Time,
    Rate,
    LowerCI,
    UpperCI
  ) %>%
  
  pivot_longer(
    cols = c(
      Total_IDs,
      Events,
      Time,
      Rate,
      LowerCI,
      UpperCI
    ),
    names_to = "Metric",
    values_to = "Value"
  ) %>%
  
  mutate(
    Metric = case_when(
      Metric == "Total_IDs" ~ "People at Risk",
      Metric == "Events" ~ "Events",
      Metric == "Time" ~ "Person-Years",
      Metric == "Rate" ~ "HIV incidence (/100py)",
      Metric == "LowerCI" ~ "Lower 95%CI (/100py)",
      Metric == "UpperCI" ~ "Upper 95%CI (/100py)"
    ),
    
    # Multiply incidence and CI by 100
    Value = ifelse(
      Metric %in% c(
        "HIV incidence (/100py)",
        "Lower 95%CI (/100py)",
        "Upper 95%CI (/100py)"
      ),
      round(Value * 100, 2),
      Value
    )
  ) %>%
  
  pivot_wider(names_from = Year, values_from = Value)

