Pak_dat_short <- data %>%
  group_by(ID) %>%
  summarise(
    Study_entry = min(Date_corrected),
    Study_exit = max(Date_corrected),
    Status = last(Status)
  )




Pak_dat_short$Study_entry2 <- as.Date(Pak_dat_short$Study_entry)
Pak_dat_short$Study_exit2 <- as.Date(Pak_dat_short$Study_exit)
Pak_dat_short$total_FUP <- Pak_dat_short$Study_exit2 - Pak_dat_short$Study_entry2  

min(Pak_dat_short$total_FUP)


Pak_dat_short$total_FUP_0 <- ifelse(Pak_dat_short$total_FUP == 0, 1, 0)
table(Pak_dat_short$total_FUP_0)

subset_data <- subset(Pak_dat_short, total_FUP == 0)



####Creating lexis durataion with Epi package in R

lex_split_Pak_dat<- Epi::Lexis(
  entry = list(year = Study_entry2),
  exit  = list(year = Study_exit2),
  data = mutate_if(Pak_dat_short, lubridate::is.Date, Epi::cal.yr)
)

plyr::count(lex_split_Pak_dat$Status)

# Split observations into follow-up periods
lex_split_Pak_dat <- lex_split_Pak_dat %>% 
  Epi::splitLexis(time.scale = "year", breaks = 2012 + 0:12)

plyr::count(lex_split_Pak_dat$Status)


# Correct HIV status because now we have the last status applied throughout
lex_split_Pak_dat <- lex_split_Pak_dat %>%
  group_by(ID) %>%
  mutate(last_visit = ifelse(row_number() == n(), 1, 0))

plyr::count(lex_split_Pak_dat$Status)

table(lex_split_Pak_dat$Status)
lex_split_Pak_dat$final_status <- ifelse(lex_split_Pak_dat$last_visit == 0, 'Negative', lex_split_Pak_dat$Status)
table(lex_split_Pak_dat$final_status) # 10878 incident cases, right?







lex_split_Pak_dat$final_status_num <- ifelse(lex_split_Pak_dat$final_status == "Positive", 1, 0)
table(lex_split_Pak_dat$final_status_num) # 10878 incident cases, right?

lex_split_Pak_dat$lex.dur


lex_split_Pak_dat$Time<-floor(lex_split_Pak_dat$year)





##incidence by province

incidence_data_prepared_all<-lex_split_Pak_dat %>%
  group_by(ID)%>%
  summarise(total_lex_dur = sum(lex.dur),
            total_new = sum(final_status_num))



lex_split_Pak_dat %>%
  summarise(n_unique_id = n_distinct(ID))

incidence_data_prepared_all

incidence_data_prepared_all <- survRate(Surv(lex.dur, final_status_num ) ~ Time,
                                        data= lex_split_Pak_dat, ) %>%
  dplyr::select( Time, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename(Overall=Time,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
                'UpperCI'= upper)



incidence_data_prepared_all


write.table(incidence_data_prepared_all, file = "incidence_data_prepared_all.doc", sep = ",", quote = FALSE, row.names = F)


