library(dplyr)
library(tidyr)

# Function to format rates with 95% CI
format_rate <- function(rate, lower, upper) {
  paste0(sprintf("%.1f", rate * 100), " (", 
         sprintf("%.1f", lower * 100), " to ", 
         sprintf("%.1f", upper * 100), ")")
}

# Combine all tables into one formatted table
incidence_table <- bind_rows(
  
  # Age groups
  incidence_data_prepared_age_all %>%
    mutate(
      Characteristic = "Age (years)",
      Subcategory = `Age group`,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Sex
  incidence_data_prepared_sex_all %>%
    mutate(
      Characteristic = "Sex",
      Subcategory = Sex,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Education status
  incidence_data_prepared_education_cat_all %>%
    mutate(
      Characteristic = "Education status",
      Subcategory = Education,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`, `Person-years`, `HIV incidence (95% CI)`),
  
  # Marital Status - combined categories
  incidence_data_prepared_married_all %>%
    mutate(
      Characteristic = "Marital Status",
      Subcategory = case_when(
        `Marital Status` %in% c("Divorced", "Separated", "Widowed") ~ "Divorced/Separated/Widowed",
        TRUE ~ `Marital Status`
      ),
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`, `Person-years`, `HIV incidence (95% CI)`),
  
  # Homelessness (current)
  incidence_data_prepared_homelessness_all %>%
    mutate(
      Characteristic = "Homelessness (current)",
      Subcategory = Homelessness,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`, `Person-years`,`HIV incidence (95% CI)`),
  
  # Incarceration for drug-related issues, past 6 months
  incidence_data_prepared_incarceration_all %>%
    mutate(
      Characteristic = "Incarceration for drug-related issues, past 6 months",
      Subcategory = Incarceration,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Place of injection
  incidence_data_prepared_place_injection_all %>%
    mutate(
      Characteristic = "Place of injection",
      Subcategory = `Place of injection`,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Injection frequency
  incidence_data_prepared_frequency_all %>%
    mutate(
      Characteristic = "Injection frequency",
      Subcategory = `Injection frequency`,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Syringe re-use
  incidence_data_prepared_syringe_reuse_all %>%
    mutate(
      Characteristic = "Syringe re-use at last injection",
      Subcategory = as.character(`Syringe re-use`),
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`),
  
  # Time since first drug injection
  incidence_data_prepared_duration_all %>%
    mutate(
      Characteristic = "Time since first drug injection",
      Subcategory = `Time since first injection`,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`, `Person-years`,`HIV incidence (95% CI)`),
  
  # Injection by street doctor, past 6 months
  incidence_data_prepared_street_doc_all %>%
    mutate(
      Characteristic = "Injection by street doctor, past 6 months",
      Subcategory = `Street doctor`,
      `Number of PWID` = Total_IDs,
      `HIV acquisition` = Events,
      `Person-years` = sprintf("%.1f", Time),  # Format with 1 decimal place
      `HIV incidence (95% CI)` = format_rate(Rate, LowerCI, UpperCI)
    ) %>%
    select(Characteristic, Subcategory, `Number of PWID`, `HIV acquisition`,`Person-years`, `HIV incidence (95% CI)`)
)

# View the complete table
print(incidence_table, n = 100)
# Define the order of Characteristics
characteristic_order <- c(
  "Age (years)",
  "Sex",
  "Education status",
  "Marital Status",
  "Homelessness (current)",
  "Incarceration for drug-related issues, past 6 months",
  "Place of injection",
  "Injection frequency",
  "Syringe re-use at last injection",
  "Time since first drug injection",
  "Injection by street doctor, past 6 months"
)

# Define the order of Subcategories for each Characteristic
# Note: All values must be unique
subcategory_order <- c(
  # Age (years)
  "<20", "20 - 29", "30 - 39", "40+",
  
  # Sex
  "Female", "Male", "Transgender",
  
  # Education status
  "No education", "Primary", "Secondary", "Higher secondary", "College or more", "Not reported",
  
  # Marital Status
  "Unmarried", "Married", "Divorced/Separated/Widowed", "Not reported",
  
  # Homelessness (current) - Using unique labels
  "No", "Yes",
  
  # Incarceration for drug-related issues, past 6 months - Using unique labels
  "No", "Yes",
  
  # Place of injection
  "Home or indoor", "Public spaces", "Not reported",
  
  # Injection frequency
  "No recent injection (>3 months ago)", 
  "Recent injection (not daily)", 
  "Daily injection (once)", 
  "Daily injection (2 times)", 
  "Daily injection (3 times)", 
  "Daily injection (4 to 5 times)", 
  "Daily injection (6 or more times)", 
  "Not reported",
  
  # Syringe re-use at last injection
  "No syringe re-use", 
  "Yes, re-used own syringe", 
  "Yes, re-used someone else’s syringe", 
  "Not reported",
  
  # Time since first drug injection
  "Up to 1 year", "Up to 2 years", "Up to 5 years", "More than 5 years",
  
  # Injection by street doctor, past 6 months - Using unique labels
  "No", "Yes"
)

# Remove duplicates from subcategory_order while preserving order
subcategory_order <- unique(subcategory_order)

# Convert to factors with specified orders
incidence_table <- incidence_table %>%
  mutate(
    Characteristic = factor(Characteristic, levels = characteristic_order),
    Subcategory = factor(Subcategory, levels = subcategory_order)
  ) %>%
  arrange(Characteristic, Subcategory)

# View the complete table
print(incidence_table, n = 100)

# Export to CSV
write.csv(incidence_table, "incidence_table_complete.csv", row.names = FALSE)

# If you want to export to Excel
# install.packages("openxlsx")
library(openxlsx)
write.xlsx(incidence_table, "incidence_table_complete.xlsx")

# For nicer viewing in R
library(knitr)
kable(incidence_table, format = "markdown", caption = "HIV incidence among PWID by demographic and behavioral characteristics")

