inc_plot_punjab <- ggplot(data = incidence_data_prepared_province_punjab, aes(x = incidence_data_prepared_province_punjab$Year, y = incidence_data_prepared_province_punjab$Rate*100, group=1)) +
  geom_ribbon(aes( ymin = LowerCI*100, ymax = UpperCI*100),fill="darkred",alpha=0.25)+
  geom_point() + geom_line(aes(group = 1)) + 
  #geom_errorbar(aes(x = incidence_rate_prepared$Year, ymin = incidence_rate_prepared$LowerCI*100, ymax = incidence_rate_prepared$UpperCI*100),color="darkgreen",width=0.1,size=.5)+
  xlab("Year") +
  ylab("\n\n\n\n\nIncidence estimate (per 100 person-years)") +
  expand_limits(y=0) +  
  labs(
    #x = "\nAdjusted Odds Ratio (aOR)",
    #y = "Syringe Use Categories\n",
    title = "Punjab\n\n",
    caption = expression(paste(italic("*Note: Data for 2024 is incomplete")))
    
  )+
  scale_x_discrete(
    breaks = c("2012", "2014", "2016", "2018", "2020", "2022", "2024")
  ) +
  #geom_vline(xintercept=c("2020"), linetype="dashed", size=1, col="red")+
  #annotate(x=9,y=10,label="Covid-19",vjust=2,geom="label", col="red")+
  theme(text=element_text(size=14), #change font size of all text
        axis.text=element_text(size=14), #change font size of axis text
        axis.title=element_text(size=14), #change font size of axis titles
        plot.title=element_text(size=14), #change font size of plot title
        legend.text=element_text(size=14), #change font size of legend text
        legend.title=element_text(size=14), #change font size of legend title 
        axis.line = element_line(color = "black"),
        axis.ticks = element_line(color = "black"),
        strip.text = element_text(size = 14),
        panel.background = element_rect(fill = "white"),  # Corrected
        plot.background = element_rect(fill = "white"),
        
        panel.grid.major = element_line(color = "gray95", linewidth = 0.3),
        panel.grid.minor = element_line(color = "gray95", linewidth = 0.15),
  )   # chnage front size of facet wrap

inc_plot_punjab
#HIV incidence (/100py)

incidence_data_prepared_province_punjab<-incidence_data_prepared_province_punjab%>%
  mutate(
    Time = sprintf("%.0f", Time)  # Format here
  ) 
incidence_data_prepared_province_punjab$Time<-as.numeric(incidence_data_prepared_province_punjab$Time)
risk_table_Pak_dat_punjab <- incidence_data_prepared_province_punjab %>%
  select(Year, Total_IDs, Events, Time, Rate) %>%
  pivot_longer(cols = c(Total_IDs, Events, Time, Rate), names_to = "Metric", values_to = "Value") %>%
  mutate(Metric = case_when(
    Metric == "Total_IDs" ~ "People at Risk",
    Metric == "Events" ~ "Events",
    Metric == "Time" ~ "Person-Years",
    Metric == "Rate" ~ "HIV incidence (/100py)"
  ),
  # multiply incidence ×100 and round
  Value = ifelse(Metric == "HIV incidence (/100py)",
                 round(Value * 100, 2),
                 Value)) %>%
  pivot_wider(names_from = Year, values_from = Value)
risk_table_Pak_dat_punjab

risk_table_Pak_dat_punjab$Metric
metric_names_punjab <- risk_table_Pak_dat_punjab$Metric
metric_names_punjab
# Convert to a matrix for tableGrob
risk_table_Pak_dat_punjab <- as.matrix(risk_table_Pak_dat_punjab[, -1])

rownames(risk_table_Pak_dat_punjab) <- metric_names_punjab

# Create a table for the risk data

# Create a tableGrob with proper alignment
table_grob_Pak_dat_punjab <- tableGrob(
  risk_table_Pak_dat_punjab,
  theme = ttheme_minimal(
    base_size = 10,
    core = list(
      bg_params = list(fill = "white", col = "black"),
      fg_params = list(hjust = 0, x = 0.1)  # Left-align text
    ),
    rowhead = list(fg_params = list(fontface = "bold"))
  )
)   
# Combine plot and table with aligned widths
final_plot_Pak_dat_punjab <- grid.arrange(
  inc_plot_punjab,
  table_grob_Pak_dat_punjab,
  nrow = 2,
  heights = c(3.1, 1.2),  # Plot takes 3/4, table takes 1/4
  widths = unit(.73, "npc")  # Ensure same width
)
