####Creating lexis durataion with Epi package in R

lex_split_inc_rate<- Epi::Lexis(
  entry = list(year = Study_entry2),
  exit  = list(year = Study_exit2),
  data = mutate_if(inc_rate, lubridate::is.Date, Epi::cal.yr)
)

lex_split_inc_rate

# Split observations into follow-up periods
lex_split_inc_rate <- lex_split_inc_rate %>% 
  Epi::splitLexis(time.scale = "year", breaks = 2012 + 0:13)




# Correct HIV status because now we have the last status applied throughout
lex_split_inc_rate <- lex_split_inc_rate %>%
  group_by(ID) %>%
  mutate(last_visit = ifelse(row_number() == n(), 1, 0))



table(lex_split_inc_rate$Status)
lex_split_inc_rate$final_status <- ifelse(lex_split_inc_rate$last_visit == 0, 'Negative', lex_split_inc_rate$Status)
table(lex_split_inc_rate$final_status) # 10878 incident cases, right?






lex_split_inc_rate$final_status_num <- ifelse(lex_split_inc_rate$final_status == "Positive", 1, 0)
table(lex_split_inc_rate$final_status_num) # 10878 incident cases, right?

lex_split_inc_rate$lex.dur


lex_split_inc_rate$Time<-floor(lex_split_inc_rate$year)

lex_split_inc_rate %>% summarise(n_unique_id = n_distinct(ID))


lex_split_inc_rate %>%
  group_by(Province) %>%
  summarise(n_unique_id = n_distinct(ID))

incidence_data_prepared_inc_rate<-lex_split_inc_rate %>%
  group_by(year = floor(year)) %>%
  summarise(total_lex_dur = sum(lex.dur),
            total_new = sum(final_status_num))



overall_incidence_inc_rate<- survRate(Surv(lex.dur, final_status_num ) ~ 1,
                                      data= lex_split_inc_rate) %>%
  dplyr::select(1, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename('Overall' = 1,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
