incidence_rate_prepared<-incidence_rate_prepared%>%
  mutate(
    Time = sprintf("%.0f", Time)  # Format here
  ) 
incidence_rate_prepared$Time<-as.numeric(incidence_rate_prepared$Time)
incidence_rate_prepared
risk_table_Pak_dat <- incidence_rate_prepared %>%
  select(Year, Total_IDs, Events, Time, Rate) %>%
  pivot_longer(cols = c(Total_IDs, Events, Time, Rate), names_to = "Metric", values_to = "Value") %>%
  mutate(Metric = case_when(
    Metric == "Total_IDs" ~ "People at Risk",
    Metric == "Events" ~ "Events",
    Metric == "Time" ~ "Person-Years",
    Metric == "Rate" ~ "HIV incidence (/100py)"
  ),
  # multiply incidence ×100 and round
  Value = ifelse(Metric == "HIV incidence (/100py)",
                 round(Value * 100, 2),
                 Value)) %>%
  pivot_wider(names_from = Year, values_from = Value)
risk_table_Pak_dat

risk_table_Pak_dat$Metric
metric_names <- risk_table_Pak_dat$Metric
metric_names
# Convert to a matrix for tableGrob
risk_table_Pak_dat <- as.matrix(risk_table_Pak_dat[, -1])
#rownames(risk_table_Pak_dat) <- risk_table_Pak_dat[["Metric"]]
rownames(risk_table_Pak_dat) <- metric_names
risk_table_Pak_dat
#colnames(risk_table_Pak_dat) <- c(2012:2024)
#rownames(risk_table_Pak_dat) <- c("People at Risk", "Events", "Person-Years")

# Create a table for the risk data

# Create a tableGrob with proper alignment
table_grob_Pak_dat <- tableGrob(
  risk_table_Pak_dat,
  theme = ttheme_minimal(
    base_size = 10,
    core = list(
      bg_params = list(fill = "white", col = "black"),
      fg_params = list(hjust = 0, x = 0.1)  # Left-align text
    ),
    rowhead = list(fg_params = list(fontface = "bold"))
  )
)   
# Combine plot and table with aligned widths
final_plot_Pak_dat <- grid.arrange(
  inc_plot,
  table_grob_Pak_dat,
  nrow = 2,
  heights = c(3, 1.2),  # Plot takes 3/4, table takes 1/4
  widths = unit(.73, "npc")  # Ensure same width
)
# Display the final plot
print(final_plot_Pak_dat)




final_plot_Pak_dat



library(grid)
