inc_rate_p$Study_entry2 <- as.Date(inc_rate_p$Study_entry)
inc_rate_p$Study_exit2 <- as.Date(inc_rate_p$Study_exit)
inc_rate_p$total_FUP <- inc_rate_p$Study_exit2 - inc_rate_p$Study_entry2  

min(inc_rate_p$total_FUP)


inc_rate_p$total_FUP_0 <- ifelse(inc_rate_p$total_FUP == 0, 1, 0)
table(inc_rate_p$total_FUP_0)

subset_inc_rate_p <- subset(inc_rate_p, total_FUP == 0)



####Creating lexis durataion with Epi package in R

lex_split_inc_rate_p<- Epi::Lexis(
  entry = list(year = Study_entry2),
  exit  = list(year = Study_exit2),
  data = mutate_if(inc_rate_p, lubridate::is.Date, Epi::cal.yr)
)



# Split observations into follow-up periods
lex_split_inc_rate_p <- lex_split_inc_rate_p %>% 
  Epi::splitLexis(time.scale = "year", breaks = 2012 + 0:12)




# Correct HIV status because now we have the last status applied throughout
lex_split_inc_rate_p <- lex_split_inc_rate_p %>%
  group_by(ID) %>%
  mutate(last_visit = ifelse(row_number() == n(), 1, 0))



table(lex_split_inc_rate_p$Status)
lex_split_inc_rate_p$final_status <- ifelse(lex_split_inc_rate_p$last_visit == 0, 'Negative', lex_split_inc_rate_p$Status)
table(lex_split_inc_rate_p$final_status) 






lex_split_inc_rate_p$final_status_num <- ifelse(lex_split_inc_rate_p$final_status == "Positive", 1, 0)
table(lex_split_inc_rate_p$final_status_num)

lex_split_inc_rate_p$lex.dur


lex_split_inc_rate_p$Time<-floor(lex_split_inc_rate_p$year)


incidence_data_prepared_inc_rate_p<-lex_split_inc_rate_p %>%
  group_by(year = floor(year)) %>%
  summarise(total_lex_dur = sum(lex.dur),
            total_new = sum(final_status_num))



overall_incidence_inc_rate_p<- survRate(Surv(lex.dur, final_status_num ) ~ 1,
                                        data= lex_split_inc_rate_p) %>%
  dplyr::select(1, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename('Overall' = 1,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
                'UpperCI'= upper)
overall_incidence_inc_rate_p


#write.table(overall_incidence_inc_rate_p, file = "overall_incidence_inc_rate_maximum_follow_up_year_punjab.doc", sep = ",", quote = FALSE, row.names = F)


incidence_rate_prepared_inc_rate_p <- survRate(Surv(lex.dur, final_status_num ) ~ Time,
                                               data= lex_split_inc_rate_p) %>%
  dplyr::select(Time, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename(Year = Time,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
                'UpperCI'= upper)





incidence_rate_prepared_inc_rate_p



incidence_rate_prepared_inc_rate_p$Year<-as.factor(incidence_rate_prepared_inc_rate_p$Year)
