inc_rate_b$total_FUP <- inc_rate_b$Study_exit2 - inc_rate_b$Study_entry2  

min(inc_rate_b$total_FUP)


inc_rate_b$total_FUP_0 <- ifelse(inc_rate_b$total_FUP == 0, 1, 0)
table(inc_rate_b$total_FUP_0)

subset_inc_rate_b <- subset(inc_rate_b, total_FUP == 0)



####Creating lexis durataion with Epi package in R

lex_split_inc_rate_b<- Epi::Lexis(
  entry = list(year = Study_entry2),
  exit  = list(year = Study_exit2),
  data = mutate_if(inc_rate_b, lubridate::is.Date, Epi::cal.yr)
)



# Split observations into follow-up periods
lex_split_inc_rate_b <- lex_split_inc_rate_b %>% 
  Epi::splitLexis(time.scale = "year", breaks = 2012 + 0:12)




# Correct HIV status because now we have the last status applied throughout
lex_split_inc_rate_b <- lex_split_inc_rate_b %>%
  group_by(ID) %>%
  mutate(last_visit = ifelse(row_number() == n(), 1, 0))



table(lex_split_inc_rate_b$Status)
lex_split_inc_rate_b$final_status <- ifelse(lex_split_inc_rate_b$last_visit == 0, 'Negative', lex_split_inc_rate_b$Status)
table(lex_split_inc_rate_b$final_status) 






lex_split_inc_rate_b$final_status_num <- ifelse(lex_split_inc_rate_b$final_status == "Positive", 1, 0)
table(lex_split_inc_rate_b$final_status_num) 

lex_split_inc_rate_b$lex.dur


lex_split_inc_rate_b$Time<-floor(lex_split_inc_rate_b$year)


incidence_data_prepared_inc_rate_b<-lex_split_inc_rate_b %>%
  group_by(year = floor(year)) %>%
  summarise(total_lex_dur = sum(lex.dur),
            total_new = sum(final_status_num))



overall_incidence_inc_rate_b<- survRate(Surv(lex.dur, final_status_num ) ~ 1,
                                        data= lex_split_inc_rate_b) %>%
  dplyr::select(1, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename('Overall' = 1,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
                'UpperCI'= upper)
overall_incidence_inc_rate_b


