incidence_rate_prepared_inc_rate_b <- survRate(Surv(lex.dur, final_status_num ) ~ Time,
                                               data= lex_split_inc_rate_b) %>%
  dplyr::select(Time, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename(Year = Time,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
