incidence_rate_prepared_inc_rate_psb2<-incidence_rate_prepared_inc_rate_psb2%>%
  mutate(
    Time = sprintf("%.0f", Time)  # Format here
  ) 
incidence_rate_prepared_inc_rate_psb2$Time<-as.numeric(incidence_rate_prepared_inc_rate_psb2$Time)
risk_table_long_psb2 <- incidence_rate_prepared_inc_rate_psb2 %>%
  select(Year, Total_IDs, Events, Time, Rate) %>%
  pivot_longer(cols = c(Total_IDs, Events, Time, Rate), names_to = "Metric", values_to = "Value") %>%
  mutate(Metric = case_when(
    Metric == "Total_IDs" ~ "People at Risk",
    Metric == "Events" ~ "Events",
    Metric == "Time" ~ "Person-Years",
    Metric == "Rate" ~ "HIV incidence (/100py)"
  ),
  # multiply incidence ×100 and round
  Value = ifelse(Metric == "HIV incidence (/100py)",
                 round(Value * 100, 2),
                 Value)) %>%
  pivot_wider(names_from = Year, values_from = Value)

# Convert to a matrix for tableGrob
risk_table_matrix_psb2<- as.matrix(risk_table_long_psb2[, -1])
rownames(risk_table_matrix_psb2) <- risk_table_long_psb2$Metric

risk_table_matrix_psb2
# Create a table for the risk data

# Create a tableGrob with proper alignment
table_grob_psb2 <- tableGrob(
  risk_table_matrix_psb2,
  theme = ttheme_minimal(
    base_size = 10,
    core = list(
      bg_params = list(fill = "white", col = "black"),
      fg_params = list(hjust = 0, x = 0.1)  # Left-align text
    ),
    rowhead = list(fg_params = list(fontface = "bold"))
  )
)   
# Combine plot and table with aligned widths
final_plot_psb2 <- grid.arrange(
  PSB2,
  table_grob_psb2,
  nrow = 2,
  heights = c(3, 1),  # Plot takes 3/4, table takes 1/4
  widths = unit(.74, "npc")  # Ensure same width
)
# Display the final plot
print(final_plot_psb2)




