Punjab_cities<-ggplot(data = incidence_rate_by_province_city2 %>%
                        filter(Province == "Punjab") %>%
                        mutate(Year = as.numeric(as.character(Year))), 
                      aes(x = Year, y = Rate * 100, group = 1)) +
  geom_ribbon(aes(ymin = LowerCI * 100, ymax = UpperCI * 100), 
              fill = "darkred", alpha = 0.25) +  # Confidence interval
  geom_point(size = 1.8) + 
  geom_line(linetype = "dashed", color = "red", size = 1) + 
  #  geom_errorbar(aes(ymin = LowerCI * 100, ymax = UpperCI * 100), 
  #               color = "darkgreen", width = 0.1, size = 0.5) +
  facet_wrap(~ City_Name, scales = "free", drop = TRUE, nrow=3) +  # Only show cities with data
  scale_x_continuous(breaks = c(2012, 2016, 2020, 2024), limits = c(2012, 2024)) +  # Ensure full range of years
  # scale_y_continuous(breaks = c(0,20, 40, 60, 80, 100), limits = c(0,100)) +  # Ensure full range of years
  xlab("Year") +
  ylab("Incidence estimate \n(per 100 person-years)") +
  expand_limits(y = 0) + 
  ggtitle(paste("HIV incidence rate by cities in Punjab province")) +
  #theme_minimal() +
  theme(text=element_text(size=14), #change font size of all text
        axis.text=element_text(size=11), #change font size of axis text
        axis.title=element_text(size=14), #change font size of axis titles
        plot.title=element_text(size=14), #change font size of plot title
        legend.text=element_text(size=14), #change font size of legend text
        legend.title=element_text(size=14), #change font size of legend title 
        axis.line = element_line(color = "black"),
        axis.ticks = element_line(color = "black"),
        strip.text = element_text(size = 14),
        panel.background = element_rect(fill = "white"),  # Corrected
        plot.background = element_rect(fill = "white"),
        
        panel.grid.major = element_line(color = "gray95", linewidth = 0.3),
        panel.grid.minor = element_line(color = "gray95", linewidth = 0.15),
  )  


