# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)

# Function to manually compute BIC
calculate_bic_overall22 <- function(sse, num_obs, num_joinpoints_overall) {
  num_params_overall <- 2 * (num_joinpoints_overall + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_params_overall / num_obs) * log(num_obs)
  return(bic)
}

# Step 1: Fit a Baseline Linear Model
baseline_model_overall22 <- lm(rate ~ Year, data = hiv_trends_overall22)
baseline_model_overall22

# Step 2: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints_overall <- 3  # Set the maximum number of joinpoints to test
num_obs_overall <- nrow(hiv_trends_overall)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints_overall) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_overall22)^2)
    tss <- sum((hiv_trends_overall22$rate - mean(hiv_trends_overall22$rate))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs_overall)
    aic <- AIC(baseline_model_overall22)
    bic <- calculate_bic_overall22(sse, num_obs_overall, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_overall22, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model_overall22 <- segmented(baseline_model_overall22, seg.Z = ~Year, npsi = npsi)
      joinpoints_overall <- segmented_model_overall$psi[, "Est."]
      sse <- sum(residuals(segmented_model_overall22)^2)
      tss <- sum((hiv_trends_overall22$rate - mean(hiv_trends_overall22$rate))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs_overall)
      aic <- AIC(segmented_model_overall22)
      bic <- calculate_bic_overall22(sse, num_obs_overall, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_overall22, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints_overall)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 3: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
valid_results_overall22 <- Filter(function(x) !is.null(x$AIC) && !is.null(x$BIC), results)
comparison_overall22 <- data.frame(
  npsi = seq_along(valid_results_overall22) - 1,
  AIC = sapply(valid_results_overall22, function(x) x$AIC),
  BIC = sapply(valid_results_overall22, function(x) x$BIC),
  RSS = sapply(valid_results_overall22, function(x) x$RSS),
  R2 = sapply(valid_results_overall22, function(x) x$R2),
  RMSE = sapply(valid_results_overall22, function(x) x$RMSE)
)
print("Model Comparison (AIC, BIC, R2, and RMSE):")
print(comparison_overall22)

