# Step 5: Create Plots for Each Model
plots_overall22 <- list()

for (i in seq_along(log_valid_results_overall22)) {
  log_model_info_overall22 <- log_valid_results_overall22[[i]]
  
  # Create a temporary data frame for predictions
  plot_data22 <- hiv_trends_overall22
  
  if (!is.null(log_model_info_overall22$Model)) {
    plot_data22$Segmented_Fitted <- fitted(log_model_info_overall22$Model)
  }
  
  # Create joinpoint data only if joinpoints exist
  if (!is.null(log_model_info_overall22$Joinpoints) && length(log_model_info_overall22$Joinpoints) > 0) {
    joinpoint_data_overall22 <- data.frame(
      Year = log_model_info_overall22$Joinpoints,
      rate = exp(predict(log_model_info_overall22$Model, newdata = data.frame(Year = log_model_info_overall22$Joinpoints))),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data_overall22 <- data.frame()
  }
  
  # Generate the Joinpoint Regression Plot
  p1_overall22 <- ggplot(plot_data22, aes(x = Year, y = rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +
    geom_line(aes(y = exp(Segmented_Fitted) * 100, color = "Joinpoint Regression"), size = 1.2) +
    labs(
      title = paste("Joinpoint Model with", ifelse(i == 1, 0, ifelse(is.null(log_model_info_overall22$Joinpoints), 0, length(log_model_info_overall22$Joinpoints))), "Joinpoints"),
      subtitle = paste("BIC:", round(log_model_info_overall22$BIC, 2), "| R²:", round(log_model_info_overall22$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +
    scale_color_manual(values = c("HIV Incidence" = "black", 
                                  "Joinpoint Regression" = "blue",
                                  "Breakpoints" = "red")) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(
      breaks = seq(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year), by = 4),
      limits = c(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year))
    ) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  # Add vertical red dashed lines for breakpoints
  if (nrow(joinpoint_data_overall22) > 0) {
    p1_overall22 <- p1_overall22 + geom_vline(data = joinpoint_data_overall22, aes(xintercept = Year, color = "Breakpoints"),
                                              linetype = "dashed", size = 1)
  }
  
  # Generate the APC Plot
  if (i == 1) {  # For npsi = 0
    coefs <- coef(log_model_info_overall22$Model)
    se <- sqrt(diag(vcov(log_model_info_overall22$Model)))
    
    # Define slope and standard error for the single segment
    slope <- coefs["Year"]
    se_slope <- se["Year"]
    
    # Calculate APC and 95% CI
    APC22 <- (exp(slope) - 1) * 100
    lower_CI22 <- (exp(slope - 1.96 * se_slope) - 1) * 100
    upper_CI22 <- (exp(slope + 1.96 * se_slope) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_overall22 <- data.frame(
      Segment = "Overall",
      APC = APC22,
      LowerCI = lower_CI22,
      UpperCI = upper_CI22,
      Start_Year = min(hiv_trends_overall22$Year),
      End_Year = max(hiv_trends_overall22$Year),
      Midpoint_Year = (min(hiv_trends_overall22$Year) + max(hiv_trends_overall22$Year)) / 2
    )
    
    # Create a formatted subtitle for APC
    apc_subtitle_overall22 <- paste0(
      "Overall APC: ", round(apc_data_overall22$APC, 2), "; 95% CI: (", 
      round(apc_data_overall22$LowerCI, 2), ", ", round(apc_data_overall22$UpperCI, 2), ")"
    )
    
    # Create the APC plot
    p2_overall22 <- ggplot(apc_data_overall22, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +
      scale_x_continuous(breaks = seq(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year), by = 4), 
                         limits = c(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle_overall22,
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(log_model_info_overall22$Joinpoints) && length(log_model_info_overall22$Joinpoints) > 0) {
    coefs <- coef(log_model_info_overall22$Model)
    se <- sqrt(diag(vcov(log_model_info_overall22$Model)))
    
    num_segments <- length(log_model_info_overall22$Joinpoints) + 1
    
    # Define slopes for each segment
    slopes <- numeric(num_segments)
    slopes[1] <- coefs["Year"]
    
    # Build cumulative slopes
    for (j in 1:(num_segments - 1)) {
      u_term <- paste0("U", j, ".Year")
      slopes[j + 1] <- slopes[j] + coefs[u_term]
    }
    
    # Calculate standard errors for each segment
    se_slopes <- numeric(num_segments)
    se_slopes[1] <- se["Year"]
    
    for (j in 1:(num_segments - 1)) {
      u_term <- paste0("U", j, ".Year")
      se_slopes[j + 1] <- sqrt(se_slopes[j]^2 + se[u_term]^2 + 2 * vcov(log_model_info_overall22$Model)["Year", u_term])
    }
    
    # Calculate APC and 95% CI for each segment
    APC_overall22 <- (exp(slopes) - 1) * 100
    lower_CI_overall22 <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
    upper_CI_overall22 <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_overall22 <- data.frame(
      Segment = paste("Segment", 1:num_segments),
      APC = APC_overall22,
      LowerCI = lower_CI_overall22,
      UpperCI = upper_CI_overall22,
      Start_Year = c(min(hiv_trends_overall22$Year), log_model_info_overall22$Joinpoints),
      End_Year = c(log_model_info_overall22$Joinpoints, max(hiv_trends_overall22$Year))
    )
    
    # Calculate the midpoint of each segment
    apc_data_overall22$Midpoint_Year <- (apc_data_overall22$Start_Year + apc_data_overall22$End_Year) / 2
    
    # Create a formatted subtitle
    apc_subtitle_lines22 <- paste0(
      "APC for Segment 1: ", round(apc_data_overall22$APC[1], 2), "; 95% CI: (", 
      round(apc_data_overall22$LowerCI[1], 2), ", ", round(apc_data_overall22$UpperCI[1], 2), ")"
    )
    
    for (j in 2:num_segments) {
      apc_subtitle_lines22 <- paste0(apc_subtitle_lines22, "\n",
                                     "APC for Segment ", j, ": ", round(apc_data_overall22$APC[j], 2), "; 95% CI: (", 
                                     round(apc_data_overall22$LowerCI[j], 2), ", ", round(apc_data_overall22$UpperCI[j], 2), ")"
      )
    }
    
    # Create the APC plot
    p2_overall22 <- ggplot(apc_data_overall22, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +
      geom_vline(xintercept = log_model_info_overall22$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +
      scale_x_continuous(breaks = seq(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year), by = 4), 
                         limits = c(min(hiv_trends_overall22$Year), max(hiv_trends_overall22$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle_lines22,
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else {
    p2_overall22 <- NULL
  }
  
  # Combine the Joinpoint Regression Plot and APC Plot
  if (!is.null(p2_overall22)) {
    combined_plot_overall22 <- p1_overall22 + p2_overall22 + plot_layout(nrow = 1, widths = c(1, 1))
  } else {
    combined_plot_overall22 <- p1_overall22
  }
  
  plots_overall22[[i]] <- combined_plot_overall22
}

# Arrange all combined plots in a grid
final_plot_overall22 <- wrap_plots(plots_overall22, ncol = 2)

# Display the final plot
print(final_plot_overall22)





