      UpperCI = upper_CI22,
      Start_Year = min(plot_data22$Year),
      End_Year = max(plot_data22$Year),
      Midpoint_Year = (min(plot_data22$Year) + max(plot_data22$Year)) / 2
    )
    
    # Create a formatted subtitle for APC
    apc_subtitle_overall22 <- paste0(
      "Overall APC:  ", round(apc_data_overall22$APC, 2), "; 95% CI: (", 
      round(apc_data_overall22$LowerCI, 2), ", ", round(apc_data_overall22$UpperCI, 2), ")"
    )
    
    # Create the APC plot
    apc_plot_overall22 <- ggplot(apc_data_overall22, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for the single segment
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Point at the midpoint of the segment
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence interval
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      scale_x_continuous(breaks = seq(min(plot_data22$Year), max(plot_data22$Year), by = 4), limits = c(min(plot_data22$Year), max(plot_data22$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle_overall22,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(model_info_overall22$Joinpoints) && length(model_info_overall22$Joinpoints) > 0) {
    # For npsi >= 1 (with breakpoints)
    coefs <- coef(model_info_overall22$Model)
    se <- sqrt(diag(vcov(model_info_overall22$Model)))
    
    num_segments <- length(model_info_overall22$Joinpoints) + 1
    
    # Define slopes for each segment
    slopes <- numeric(num_segments)
    slopes[1] <- coefs["Year"]
    
    # Build cumulative slopes for multiple segments
    if (num_segments > 1) {
      for (j in 1:(num_segments - 1)) {
        u_term <- paste0("U", j, ".Year")
        if (u_term %in% names(coefs)) {
          slopes[j + 1] <- slopes[j] + coefs[u_term]
        }
      }
    }
    
    # Calculate standard errors for each segment
    se_slopes <- numeric(num_segments)
    se_slopes[1] <- se["Year"]
    
    if (num_segments > 1) {
      for (j in 1:(num_segments - 1)) {
        u_term <- paste0("U", j, ".Year")
        if (u_term %in% names(se)) {
          se_slopes[j + 1] <- sqrt(se_slopes[j]^2 + se[u_term]^2 + 
                                     2 * vcov(model_info_overall22$Model)["Year", u_term])
        }
      }
    }
    
    # Calculate APC and 95% CI for each segment
    APC_overall22 <- (exp(slopes) - 1) * 100
    lower_CI_overall22 <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
    upper_CI_overall22 <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_overall22 <- data.frame(
      Segment = paste("Segment", 1:num_segments),
      APC = APC_overall22,
      LowerCI = lower_CI_overall22,
      UpperCI = upper_CI_overall22,
      Start_Year = c(min(plot_data22$Year), model_info_overall22$Joinpoints)[1:num_segments],
      End_Year = c(model_info_overall22$Joinpoints, max(plot_data22$Year))[1:num_segments]
    )
    
    # Create a formatted subtitle with each segment on a separate line
    apc_subtitle_lines22 <- paste0(
      "APC for Segment 1:  ", round(apc_data_overall22$APC[1], 2), "; 95% CI: (", 
      round(apc_data_overall22$LowerCI[1], 2), ", ", round(apc_data_overall22$UpperCI[1], 2), ")"
    )
    
    for (j in 2:num_segments) {
      apc_subtitle_lines22 <- paste0(apc_subtitle_lines22, "\n",
                                     "APC for Segment ", j, ":  ", round(apc_data_overall22$APC[j], 2), "; 95% CI: (", 
                                     round(apc_data_overall22$LowerCI[j], 2), ", ", round(apc_data_overall22$UpperCI[j], 2), ")"
      )
    }
    
    # Create the APC plot
    apc_plot_overall22 <- ggplot(apc_data_overall22, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for each segment
      geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +  # Points at midpoints of each segment
      geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      geom_vline(xintercept = model_info_overall22$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
      scale_x_continuous(breaks = seq(min(plot_data22$Year), max(plot_data22$Year), by = 4)) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle_lines22,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else {
    apc_plot_overall22 <- NULL  # No APC plot when no joinpoints exist
  }
  
  # Combine the Joinpoint Regression Plot and APC Plot
  if (!is.null(apc_plot_overall22)) {
    combined_plot_overall22 <- incidence_plot_overall22 + apc_plot_overall22 + plot_layout(nrow = 1)  # Combine horizontally
  } else {
    combined_plot_overall22 <- incidence_plot_overall22  # Only Joinpoint Regression Plot
  }
  
  plots_overall22[[i]] <- combined_plot_overall22  # Store each combined plot
}

