# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)

# Function to manually compute BIC
calculate_bic <- function(sse, num_obs, num_joinpoints) {
  num_params <- 2 * (num_joinpoints + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_params / num_obs) * log(num_obs)
  return(bic)
}

# Step 1: Fit a Baseline Linear Model
baseline_model <- lm(rate ~ Year, data = hiv_trends)
baseline_model
# Step 2: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints <- 3  # Set the maximum number of joinpoints to test
num_obs <- nrow(hiv_trends)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model)^2)
    tss <- sum((hiv_trends$rate - mean(hiv_trends$rate))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model)
    bic <- calculate_bic(sse, num_obs, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model <- segmented(baseline_model, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model$psi[, "Est."]
      sse <- sum(residuals(segmented_model)^2)
      tss <- sum((hiv_trends$rate - mean(hiv_trends$rate))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model)
      bic <- calculate_bic(sse, num_obs, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 3: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
valid_results <- Filter(function(x) !is.null(x$AIC) && !is.null(x$BIC), results)
comparison <- data.frame(
  npsi = seq_along(valid_results) - 1,
  AIC = sapply(valid_results, function(x) x$AIC),
  BIC = sapply(valid_results, function(x) x$BIC),
  RSS = sapply(valid_results, function(x) x$RSS),
  R2 = sapply(valid_results, function(x) x$R2),
  RMSE = sapply(valid_results, function(x) x$RMSE)
)
print("Model Comparison (AIC, BIC, R2, and RMSE):")
print(comparison)
