# Step 4: Create Plots for Each Model
plots <- list()

for (i in seq_along(valid_results)) {
  log_model_info <- valid_results[[i]]
  
  if (!is.null(log_model_info$Model) && length(predict(log_model_info$Model)) == nrow(hiv_trends)) {
    hiv_trends$Segmented_Fitted <- predict(log_model_info$Model)
  }
  
  # Create joinpoint data only if joinpoints exist
  if (!is.null(log_model_info$Joinpoints)) {
    joinpoint_data <- data.frame(
      Year = log_model_info$Joinpoints,
      rate = predict(log_model_info$Model, newdata = data.frame(Year = log_model_info$Joinpoints)),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data <- data.frame()
  }
  
  # Generate the Joinpoint Regression Plot
  p1 <- ggplot(hiv_trends, aes(x = Year, y = rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +  # Black dots
    geom_line(aes(y = Segmented_Fitted * 100, color = "Joinpoint Regression"), size = 1.2) +  # Blue line
    labs(
      title = paste("Joinpoint Model with", i - 1, "Joinpoints"),
      subtitle = paste("BIC:", round(log_model_info$BIC, 2), "| R²:", round(log_model_info$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +
    scale_color_manual(values = c("HIV Incidence" = "black", 
                                  "Joinpoint Regression" = "blue",
                                  "Breakpoints" = "red")) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(
      breaks = seq(min(hiv_trends$Year), max(hiv_trends$Year), by = 4),
      limits = c(min(hiv_trends$Year), max(hiv_trends$Year))
    ) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  # Add vertical red dashed lines for breakpoints
  if (nrow(joinpoint_data) > 0) {
    p1 <- p1 + geom_vline(data = joinpoint_data, aes(xintercept = Year, color = "Breakpoints"),
                          linetype = "dashed", size = 1)
  }
  
  # Generate the APC Plot
  if (i == 1) {  # For npsi = 0
    coefs <- coef(log_model_info$Model)
    se <- sqrt(diag(vcov(log_model_info$Model)))
    
    # Define slope and standard error for the single segment
    slope <- coefs["Year"]
    se_slope <- se["Year"]
    
    # Calculate APC and 95% CI
    APC <- (exp(slope) - 1) * 100
    lower_CI <- (exp(slope - 1.96 * se_slope) - 1) * 100
    upper_CI <- (exp(slope + 1.96 * se_slope) - 1) * 100
    
    # Create a data frame to store the results
    apc_data <- data.frame(
      Segment = "Overall",
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI,
      Start_Year = min(hiv_trends$Year),
      End_Year = max(hiv_trends$Year),
      Midpoint_Year = (min(hiv_trends$Year) + max(hiv_trends$Year)) / 2
    )
    
    # Create a formatted subtitle for APC
    apc_subtitle <- paste0(
      "Overall APC:  ", round(apc_data$APC, 2), "; 95% CI: (", 
      round(apc_data$LowerCI, 2), ", ", round(apc_data$UpperCI, 2), ")"
    )
    
    # Create the APC plot
    p2 <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for the single segment
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Point at the midpoint of the segment
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence interval
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      scale_x_continuous(breaks = seq(min(hiv_trends$Year), max(hiv_trends$Year), by = 4), limits = c(min(hiv_trends$Year), max(hiv_trends$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(log_model_info$Joinpoints)) {
    # Existing APC plot code for npsi >= 1
    coefs <- coef(log_model_info$Model)
    se <- sqrt(diag(vcov(log_model_info$Model)))
    
    # Define slopes for each segment
    slopes <- c(
      coefs["Year"], # Slope before the first breakpoint
      if (i >= 2) coefs["Year"] + coefs["U1.Year"], # Slope between the first and second breakpoints
      if (i >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"], # Slope between the second and third breakpoints
      if (i >= 4) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"] # Slope after the third breakpoint
    )
    
    # Define standard errors for each segment
    se_slopes <- c(
      se["Year"], # SE for slope before the first breakpoint
      if (i >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(log_model_info$Model)["Year", "U1.Year"]), # SE for slope between the first and second breakpoints
      if (i >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                         2 * vcov(log_model_info$Model)["Year", "U1.Year"] + 
                         2 * vcov(log_model_info$Model)["Year", "U2.Year"] + 
                         2 * vcov(log_model_info$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
      if (i >= 4) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                         2 * vcov(log_model_info$Model)["Year", "U1.Year"] + 
                         2 * vcov(log_model_info$Model)["Year", "U2.Year"] + 
                         2 * vcov(log_model_info$Model)["Year", "U3.Year"] + 
                         2 * vcov(log_model_info$Model)["U1.Year", "U2.Year"] + 
                         2 * vcov(log_model_info$Model)["U1.Year", "U3.Year"] + 
                         2 * vcov(log_model_info$Model)["U2.Year", "U3.Year"]) # SE for slope after the third breakpoint
    )
    
    # Calculate APC and 95% CI for each segment
    APC <- (exp(slopes) - 1) * 100
    lower_CI <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
    upper_CI <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data <- data.frame(
      Segment = c("Segement", "Segement 2", "Segement 3", "Segement 4")[1:length(slopes)],
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI
    )
    
    # Rename columns for plotting
    colnames(apc_data) <- c("Segment", "APC", "LowerCI", "UpperCI")
    
    # Add a Start_Year column to the results data frame for plotting
    apc_data$Start_Year <- c(min(hiv_trends$Year), log_model_info$Joinpoints)[1:length(slopes)]
    apc_data$End_Year <- c(log_model_info$Joinpoints, max(hiv_trends$Year))[1:length(slopes)]
    
    # Calculate the midpoint of each segment for geom_point and geom_errorbar
    apc_data$Midpoint_Year <- (apc_data$Start_Year + apc_data$End_Year) / 2
    
    # Create a formatted subtitle with each segment on a separate line
    apc_subtitle <- paste0(
      "APC for Segement 1:  ", round(apc_data$APC[1], 2), "; 95% CI: (", 
      round(apc_data$LowerCI[1], 2), ", ", round(apc_data$UpperCI[1], 2), ")\n",
      if (i >= 2) paste0("APC for Segement 2:  ", round(apc_data$APC[2], 2), "; 95% CI: (", 
                         round(apc_data$LowerCI[2], 2), ", ", round(apc_data$UpperCI[2], 2), ")\n"),
      if (i >= 3) paste0("APC for Segement 3:  ", round(apc_data$APC[3], 2), "; 95% CI: (", 
                         round(apc_data$LowerCI[3], 2), ", ", round(apc_data$UpperCI[3], 2), ")\n"),
      if (i >= 4) paste0("APC for Segement 4:  ", round(apc_data$APC[4], 2), "; 95% CI: (", 
                         round(apc_data$LowerCI[4], 2), ", ", round(apc_data$UpperCI[4], 2), ")")
    )
    
    # Create the APC plot
    p2 <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for each segment
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Points at midpoints of each segment
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      geom_vline(xintercept = log_model_info$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
      scale_x_continuous(breaks = seq(min(hiv_trends$Year), max(hiv_trends$Year), by = 4), limits = c(min(hiv_trends$Year), max(hiv_trends$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else {
    p2 <- NULL  # No APC plot for npsi = 0
  }
  
  # Combine the Joinpoint Regression Plot and APC Plot
  if (!is.null(p2)) {
    combined_plot <- p1 + p2 + plot_layout(nrow = 1)  # Combine horizontally
  } else {
    combined_plot <- p1  # Only Joinpoint Regression Plot for npsi = 0
  }
  
  plots[[i]] <- combined_plot  # Store each combined plot
}

