  lower_CI <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
  upper_CI <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
  
  # Create a data frame to store the results
  apc_data <- data.frame(
    Segment = paste("Segment", 1:length(slopes)),
    APC = APC,
    LowerCI = lower_CI,
    UpperCI = upper_CI,
    Start_Year = c(min(data$Year), best_model_info$Joinpoints)[1:length(slopes)],
    End_Year = c(best_model_info$Joinpoints, max(data$Year))[1:length(slopes)]
  )
}
