  geom_col(data = apc_data %>% filter(APC < 0), 
           aes(x = (Start_Year + End_Year)/2, 
               y = -abs(APC) * apc_scale_factor,
               fill = Segment), 
           width = 0.8, alpha = 0.7, position = position_nudge(y = apc_offset)) +
  # Error bars for APC
  geom_errorbar(data = apc_data, 
                aes(x = (Start_Year + End_Year)/2, 
                    ymin = LowerCI * apc_scale_factor + apc_offset, 
                    ymax = UpperCI * apc_scale_factor + apc_offset),
                width = 0.5, size = 0.8, color = "black") +
  
  # Baseline reference line
  geom_hline(yintercept = apc_offset, linetype = "dashed", color = "black", alpha = 0.7, size = 1) +
  
  # Dual y-axis scales
  scale_y_continuous(
    name = "HIV Incidence Rate (per 100 person-years)",
    sec.axis = sec_axis(~(. - apc_offset) / apc_scale_factor, name = "Annual Percentage Change (%)")
  ) +
  scale_color_manual(
    name = "Incidence Estimates",
    values = c(
      "Empirical estimates" = "red",
      "Model fitted estimates" = "blue"
    ),
    guide = guide_legend(override.aes = list(
      linetype = c("solid", "dashed"),
      shape = c(16, NA)
    ))
  ) +
  scale_fill_manual(
    name = "APC Segments",
    values = c(
      "Overall" = "darkgreen",
      "Segment 1" = "darkgreen",
      "Segment 2" = "purple", 
      "Segment 3" = "orange",
      "Segment 4" = "brown"
    )
  ) +
  scale_x_continuous(breaks = seq(min(data$Year, na.rm = TRUE), max(data$Year, na.rm = TRUE), by = 4)) +
  labs(
    title = "HIV Trend Analysis with Joinpoint Regression and APC",
    subtitle = paste("Best Joinpoint Model with", best_npsi, "Joinpoints |", 
                     "BIC:", round(best_model_info$BIC, 2), "| R²:", round(best_model_info$R2, 3), "|",
                     apc_subtitle),
    caption = "*Note: Data for 2024 is incomplete\nRed vertical dashed lines show join points where incidence changes direction\nGray ribbon shows 95% confidence interval for empirical estimates",
    x = "Year",
    y = "Incidence estimate \n(per 100 person-years)"
  ) +
  expand_limits(y = 0) +
  theme_minimal() +
  theme(
    text = element_text(size = 14),
    axis.text = element_text(size = 14),
    axis.title = element_text(size = 14),
    plot.title = element_text(size = 16, face = "bold"),
    plot.subtitle = element_text(size = 11),
    plot.caption = element_text(size = 10, hjust = 0),
    legend.text = element_text(size = 11),
    legend.title = element_text(size = 12, face = "bold"),
    axis.text.x = element_text(angle = 45, hjust = 1),
    legend.position = "bottom",
    legend.box = "vertical",
    legend.margin = margin(t = 5, b = 5),
    axis.title.y.left = element_text(color = "black"),
    axis.text.y.left = element_text(color = "black"),
    axis.title.y.right = element_text(color = "darkgreen"),
    axis.text.y.right = element_text(color = "darkgreen")
  )

