# JPC plots: Create Plots for Each Model
plots2 <- list()

for (i in seq_along(valid_results)) {
  model_info <- valid_results[[i]]
  npsi <- comparison$npsi[i]
  
  # Add fitted values to the data
  if (!is.null(model_info$Model) && length(predict(model_info$Model)) == nrow(data)) {
    data$Segmented_Fitted <- predict(model_info$Model)
  }
  
  # Create joinpoint data only if joinpoints exist
  if (!is.null(model_info$Joinpoints)) {
    joinpoint_data <- data.frame(
      Year = model_info$Joinpoints,
      log_Rate = predict(model_info$Model, newdata = data.frame(Year = model_info$Joinpoints)),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data <- data.frame()
  }
  
  # Generate the Joinpoint Regression Plot
  incidence_plot <- ggplot(data, aes(x = Year, y = Rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +  # Black dots
    geom_line(aes(y = exp(Segmented_Fitted) * 100, color = "Joinpoint Regression"), size = 1.2) +  # Blue line
    labs(
      title = paste("Joinpoint Model with", npsi, "Joinpoints"),
      subtitle = paste("BIC:", round(model_info$BIC, 2), "| R²:", round(model_info$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +
    scale_color_manual(values = c("HIV Incidence" = "black", "Joinpoint Regression" = "blue", "Breakpoints" = "red")) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(breaks = seq(min(data$Year), max(data$Year), by = 4)) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  # Add breakpoints (vertical lines) only if joinpoint_data is not empty
  if (nrow(joinpoint_data) > 0) {
    incidence_plot <- incidence_plot +
      geom_vline(data = joinpoint_data, aes(xintercept = Year), linetype = "dashed", color = "red", size = 1)
  }
  
  # Generate the APC Plot
  if (npsi == 0) {
    # For npsi = 0 (no breakpoints)
    coefs <- coef(model_info$Model)
    se <- sqrt(diag(vcov(model_info$Model)))
    
    # Define slope and standard error for the single segment
    slope <- coefs["Year"]
    se_slope <- se["Year"]
    
    # Calculate APC and 95% CI
    APC <- (exp(slope) - 1) * 100
    lower_CI <- (exp(slope - 1.96 * se_slope) - 1) * 100
    upper_CI <- (exp(slope + 1.96 * se_slope) - 1) * 100
    
    # Create a data frame to store the results
    apc_data <- data.frame(
      Segment = "Overall",
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI,
      Start_Year = min(data$Year),
      End_Year = max(data$Year),
      Midpoint_Year = (min(data$Year) + max(data$Year)) / 2
    )
    
    # Create a formatted subtitle for APC
    apc_subtitle <- paste0(
      "Overall APC:  ", round(apc_data$APC, 2), "; 95% CI: (", 
      round(apc_data$LowerCI, 2), ", ", round(apc_data$UpperCI, 2), ")"
    )
    
    # Create the APC plot
    apc_plot <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for the single segment
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Point at the midpoint of the segment
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence interval
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      scale_x_continuous(breaks = seq(min(data$Year), max(data$Year), by = 4), limits = c(min(data$Year), max(data$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(model_info$Joinpoints)) {
    # For npsi >= 1 (with breakpoints)
    coefs <- coef(model_info$Model)
    se <- sqrt(diag(vcov(model_info$Model)))
    
    # Define slopes for each segment
    slopes <- c(
      coefs["Year"], # Slope before the first breakpoint
      if (npsi >= 1) coefs["Year"] + coefs["U1.Year"], # Slope between the first and second breakpoints
      if (npsi >= 2) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"], # Slope between the second and third breakpoints
      if (npsi >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"] # Slope after the third breakpoint
    )
    
    # Define standard errors for each segment
    se_slopes <- c(
      se["Year"], # SE for slope before the first breakpoint
      if (npsi >= 1) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(model_info$Model)["Year", "U1.Year"]), # SE for slope between the first and second breakpoints
      if (npsi >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                            2 * vcov(model_info$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
      if (npsi >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                            2 * vcov(model_info$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info$Model)["U2.Year", "U3.Year"]) # SE for slope after the third breakpoint
    )
    
    # Calculate APC and 95% CI for each segment
    APC <- (exp(slopes) - 1) * 100
    lower_CI <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
    upper_CI <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data <- data.frame(
      Segment = paste("Segment", 1:length(slopes)),
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI,
      Start_Year = c(min(data$Year), model_info$Joinpoints)[1:length(slopes)],
      End_Year = c(model_info$Joinpoints, max(data$Year))[1:length(slopes)]
    )
    
    # Create a formatted subtitle with each segment on a separate line
    apc_subtitle <- paste0(
      "APC for Segment 1:  ", round(apc_data$APC[1], 2), "; 95% CI: (", 
      round(apc_data$LowerCI[1], 2), ", ", round(apc_data$UpperCI[1], 2), ")\n",
      if (npsi >= 1) paste0("APC for Segment 2:  ", round(apc_data$APC[2], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[2], 2), ", ", round(apc_data$UpperCI[2], 2), ")\n"),
      if (npsi >= 2) paste0("APC for Segment 3:  ", round(apc_data$APC[3], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[3], 2), ", ", round(apc_data$UpperCI[3], 2), ")\n"),
      if (npsi >= 3) paste0("APC for Segment 4:  ", round(apc_data$APC[4], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[4], 2), ", ", round(apc_data$UpperCI[4], 2), ")")
    )
    
    # Create the APC plot
    apc_plot <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for each segment
      geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +  # Points at midpoints of each segment
      geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      geom_vline(xintercept = model_info$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
      scale_x_continuous(breaks = seq(min(data$Year), max(data$Year), by = 4)) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else {
    apc_plot <- NULL  # No APC plot for npsi = 0
  }
  
  # Combine the Joinpoint Regression Plot and APC Plot
  if (!is.null(apc_plot)) {
    combined_plot2 <- incidence_plot  + plot_layout(nrow = 1)  # Combine horizontally
  } else {
    combined_plot2 <- incidence_plot  # Only Joinpoint Regression Plot for npsi = 0
  }
  
  plots2[[i]] <- combined_plot2  # Store each combined plot
}

# Arrange all combined plots in a grid
final_plot2 <- wrap_plots(plots2, ncol = 2)  # Arrange in a 2x2 grid

# Display the final plot
print(final_plot2)

# Save the best combined plot
ggsave("Joinpoint_Regression_Plot_JPC in lor rate.jpg", height = 9, width = 13, dpi = 300)






