# Generate the APC Plot for the best model
if (best_npsi == 0) {
  # For npsi = 0 (no breakpoints)
  coefs <- coef(best_model_info$Model)
  se <- sqrt(diag(vcov(best_model_info$Model)))
  
  # Define slope and standard error for the single segment
  slope <- coefs["Year"]
  se_slope <- se["Year"]
  
  # Calculate APC and 95% CI
  APC <- (exp(slope) - 1) * 100
  lower_CI <- (exp(slope - 1.96 * se_slope) - 1) * 100
  upper_CI <- (exp(slope + 1.96 * se_slope) - 1) * 100
  
  # Create a data frame to store the results
  apc_data <- data.frame(
    Segment = "Overall",
    APC = APC,
    LowerCI = lower_CI,
    UpperCI = upper_CI,
    Start_Year = min(data$Year),
    End_Year = max(data$Year),
    Midpoint_Year = (min(data$Year) + max(data$Year)) / 2
  )
  
  # Create a formatted subtitle for APC
  apc_subtitle <- paste0(
    "Overall APC:  ", round(apc_data$APC, 2), "; 95% CI: (", 
