# Function to manually compute BIC
calculate_bic_p <- function(sse, num_obs, num_joinpoints) {
  num_params <- 2 * (num_joinpoints + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_params / num_obs) * log(num_obs)
  return(bic)
}

# Step 1: Fit a Baseline Linear Model
baseline_model_p <- lm(rate ~ Year, data = hiv_trends_p)

# Step 2: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints <- 4  # Set the maximum number of joinpoints to test
num_obs <- nrow(hiv_trends_p)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_p)^2)
    tss <- sum((hiv_trends_p$rate - mean(hiv_trends_p$rate))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model_p)
    bic <- calculate_bic_p(sse, num_obs, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_p, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model_p <- segmented(baseline_model_p, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model_p$psi[, "Est."]
      sse <- sum(residuals(segmented_model_p)^2)
      tss <- sum((hiv_trends_p$rate - mean(hiv_trends_p$rate))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model_p)
      bic <- calculate_bic_p(sse, num_obs, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_p, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

