# Generate the APC Plot for the best model
if (best_npsi_p == 0) {
  # For npsi = 0 (no breakpoints)
  coefs <- coef(best_model_info_p$Model)
  se <- sqrt(diag(vcov(best_model_info_p$Model)))
  
  # Define slope and standard error for the single segment
  slope <- coefs["Year"]
  se_slope <- se["Year"]
  
  # Calculate APC and 95% CI
  APC_p <- (exp(slope) - 1) * 100
  lower_CI_p <- (exp(slope - 1.96 * se_slope) - 1) * 100
  upper_CI_p <- (exp(slope + 1.96 * se_slope) - 1) * 100
  
  # Create a data frame to store the results
  apc_data_p <- data.frame(
    Segment = "Overall",
    APC = APC_p,
    LowerCI = lower_CI_p,
    UpperCI = upper_CI_p,
    Start_Year = min(data_p$Year),
    End_Year = max(data_p$Year),
    Midpoint_Year = (min(data_p$Year) + max(data_p$Year)) / 2
  )
  
  # Create a formatted subtitle for APC
  apc_subtitle_p <- paste0(
    "Overall APC:  ", round(apc_data_p$APC, 2), "; 95% CI: (", 
    round(apc_data_p$LowerCI, 2), ", ", round(apc_data_p$UpperCI, 2), ")"
  )
  
  # Create the APC plot
  apc_plot_p <- ggplot(apc_data_p, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
    geom_line(size = 1.5) +  # Continuous line for the single segment
    geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Point at the midpoint of the segment
    geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence interval
    geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
    geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
    scale_x_continuous(breaks = seq(min(data_p$Year), max(data_p$Year), by = 4), limits = c(min(data_p$Year), max(data_p$Year))) +
    scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
    labs(
      title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
      subtitle = apc_subtitle_p,  # Using the formatted subtitle
      x = "Year",
      y = "Annual Percentage Change (%)"
    ) +
    theme_minimal() +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "right"
    )
} else if (!is.null(best_model_info_p$Joinpoints)) {
  # For npsi >= 1 (with breakpoints)
  coefs <- coef(best_model_info_p$Model)
  se <- sqrt(diag(vcov(best_model_info_p$Model)))
  
  # Define slopes for each segment
  slopes <- c(
    coefs["Year"], # Slope before the first breakpoint
    if (best_npsi_p >= 1) coefs["Year"] + coefs["U1.Year"], # Slope between the first and second breakpoints
    if (best_npsi_p >= 2) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"], # Slope between the second and third breakpoints
    if (best_npsi_p >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"] # Slope after the third breakpoint
  )
  
  # Define standard errors for each segment
  se_slopes <- c(
    se["Year"], # SE for slope before the first breakpoint
    if (best_npsi_p >= 1) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(best_model_info_p$Model)["Year", "U1.Year"]), # SE for slope between the first and second breakpoints
    if (best_npsi_p >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                                 2 * vcov(best_model_info_p$Model)["Year", "U1.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
    if (best_npsi_p >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                                 2 * vcov(best_model_info_p$Model)["Year", "U1.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["Year", "U3.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["U1.Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["U1.Year", "U3.Year"] + 
                                 2 * vcov(best_model_info_p$Model)["U2.Year", "U3.Year"]) # SE for slope after the third breakpoint
  )
  
  # Calculate APC and 95% CI for each segment
  APC_p <- (exp(slopes) - 1) * 100
  lower_CI_p <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
  upper_CI_p <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
  
  # Create a data frame to store the results
  apc_data_p <- data.frame(
    Segment = paste("Segment", 1:length(slopes)),
    APC = APC_p,
    LowerCI = lower_CI_p,
    UpperCI = upper_CI_p,
    Start_Year = c(min(data_p$Year), best_model_info_p$Joinpoints)[1:length(slopes)],
    End_Year = c(best_model_info_p$Joinpoints, max(data_p$Year))[1:length(slopes)]
  )
  
  # Create a formatted subtitle with each segment on a separate line
  apc_subtitle_p <- paste0(
    "APC for Segment 1:  ", round(apc_data_p$APC[1], 2), "; 95% CI: (", 
    round(apc_data_p$LowerCI[1], 2), ", ", round(apc_data_p$UpperCI[1], 2), ")\n",
    if (best_npsi_p >= 1) paste0("APC for Segment 2:  ", round(apc_data_p$APC[2], 2), "; 95% CI: (", 
                                 round(apc_data_p$LowerCI[2], 2), ", ", round(apc_data_p$UpperCI[2], 2), ")\n"),
    if (best_npsi_p >= 2) paste0("APC for Segment 3:  ", round(apc_data_p$APC[3], 2), "; 95% CI: (", 
                                 round(apc_data_p$LowerCI[3], 2), ", ", round(apc_data_p$UpperCI[3], 2), ")\n"),
    if (best_npsi_p >= 3) paste0("APC for Segment 4:  ", round(apc_data_p$APC[4], 2), "; 95% CI: (", 
                                 round(apc_data_p$LowerCI[4], 2), ", ", round(apc_data_p$UpperCI[4], 2), ")")
  )
  
  # Create the APC plot
  apc_plot_p <- ggplot(apc_data_p, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
    geom_line(size = 1.5) +  # Continuous line for each segment
    geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +  # Points at midpoints of each segment
    geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
    geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
    geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
    geom_vline(xintercept = best_model_info_p$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
    scale_x_continuous(breaks = seq(min(data_p$Year), max(data_p$Year), by = 4)) +
    scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
    labs(
      title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
      subtitle = apc_subtitle_p,  # Using the formatted subtitle
      x = "Year",
      y = "Annual Percentage Change (%)"
    ) +
    theme_minimal() +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "right"
    )+
    scale_fill_discrete(name = " Time Segments ") +
    scale_color_discrete(name = " Time Segments ")
}

