# Function to manually compute BIC
calculate_bic_s <- function(sse, num_obs, num_joinpoints) {
  num_sarams <- 2 * (num_joinpoints + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_sarams / num_obs) * log(num_obs)
  return(bic)
}

