      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model_s)
      bic <- calculate_bic_s(sse, num_obs, npsi)  # FIXED: changed calculate_bic to calculate_bic_s
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_s, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 4: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
