comparison_s <- data.frame(
  npsi = seq_along(valid_results_s) - 1,
  AIC = sapply(valid_results_s, function(x) x$AIC),
  BIC = sapply(valid_results_s, function(x) x$BIC),
  RSS = sapply(valid_results_s, function(x) x$RSS),
