} else if (!is.null(best_model_info_s$Joinpoints)) {
  # For npsi >= 1 (with breakpoints)
  coefs <- coef(best_model_info_s$Model)
  se <- sqrt(diag(vcov(best_model_info_s$Model)))
  
  # Define slopes for each segment
  slopes <- c(
    coefs["Year"], # Slope before the first breakpoint
    if (best_npsi_s >= 1) coefs["Year"] + coefs["U1.Year"], # Slope between the first and second breakpoints
    if (best_npsi_s >= 2) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"], # Slope between the second and third breakpoints
    if (best_npsi_s >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"] # Slope after the third breakpoint
  )
  
  # Define standard errors for each segment
  se_slopes <- c(
    se["Year"], # SE for slope before the first breakpoint
    if (best_npsi_s >= 1) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(best_model_info_s$Model)["Year", "U1.Year"]), # SE for slope between the first and second breakpoints
    if (best_npsi_s >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                                 2 * vcov(best_model_info_s$Model)["Year", "U1.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
    if (best_npsi_s >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                                 2 * vcov(best_model_info_s$Model)["Year", "U1.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["Year", "U3.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["U1.Year", "U2.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["U1.Year", "U3.Year"] + 
                                 2 * vcov(best_model_info_s$Model)["U2.Year", "U3.Year"]) # SE for slope after the third breakpoint
  )
  
  # Calculate APC and 95% CI for each segment
  APC_s <- (exp(slopes) - 1) * 100
  lower_CI_s <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
  upper_CI_s <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
  
  # Create a data frame to store the results
  apc_data_s <- data.frame(
    Segment = paste("Segment", 1:length(slopes)),
    APC = APC_s,
    LowerCI = lower_CI_s,
    UpperCI = upper_CI_s,
    Start_Year = c(min(data_s$Year), best_model_info_s$Joinpoints)[1:length(slopes)],
    End_Year = c(best_model_info_s$Joinpoints, max(data_s$Year))[1:length(slopes)]
  )
  
  # Create a formatted subtitle with each segment on a separate line
  apc_subtitle_s <- paste0(
    "APC for Segment 1:  ", round(apc_data_s$APC[1], 2), "; 95% CI: (", 
    round(apc_data_s$LowerCI[1], 2), ", ", round(apc_data_s$UpperCI[1], 2), ")\n",
    if (best_npsi_s >= 1) paste0("APC for Segment 2:  ", round(apc_data_s$APC[2], 2), "; 95% CI: (", 
                                 round(apc_data_s$LowerCI[2], 2), ", ", round(apc_data_s$UpperCI[2], 2), ")\n"),
    if (best_npsi_s >= 2) paste0("APC for Segment 3:  ", round(apc_data_s$APC[3], 2), "; 95% CI: (", 
                                 round(apc_data_s$LowerCI[3], 2), ", ", round(apc_data_s$UpperCI[3], 2), ")\n"),
    if (best_npsi_s >= 3) paste0("APC for Segment 4:  ", round(apc_data_s$APC[4], 2), "; 95% CI: (", 
                                 round(apc_data_s$LowerCI[4], 2), ", ", round(apc_data_s$UpperCI[4], 2), ")")
  )
  
  # Create the APC plot
  apc_slot_s <- ggplot(apc_data_s, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
    geom_line(size = 1.5) +  # Continuous line for each segment
    geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +  # Points at midpoints of each segment
    geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
    geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
    geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
    geom_vline(xintercept = best_model_info_s$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
    scale_x_continuous(breaks = seq(min(data_s$Year), max(data_s$Year), by = 4)) +
    scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
    labs(
      title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
      subtitle = apc_subtitle_s,  # Using the formatted subtitle
      x = "Year",
      y = "Annual Percentage Change (%)"
