# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)

# Function to manually compute BIC
calculate_bic_b2 <- function(sse, num_obs, num_joinpoints) {
  num_barams <- 2 * (num_joinpoints + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_barams / num_obs) * log(num_obs)
  return(bic)
}

# Your data
data_b2 

# Step 1: Log-transform the Rate column
data_b2 <- data_b2 %>%
  mutate(log_Rate = log(Rate))
# Replace -Inf with a very small value
epsilon <- 1e-6
data_b2 <- data_b2 %>%
  mutate(
    log_Rate_fixed = ifelse(is.infinite(log_Rate), log(epsilon), log_Rate)
  )

# 
# Step 2: Fit a Baseline Linear Model
baseline_model_b2 <- lm(log_Rate_fixed ~ Year, data = data_b2)

# Step 3: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints <- 3  # Set the maximum number of joinpoints to test
num_obs <- nrow(data_b2)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_b2)^2)
    tss <- sum((data_b2$log_Rate - mean(data_b2$log_Rate_fixed))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model_b2)
    bic <- calculate_bic_b2(sse, num_obs, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_b2, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model_b2 <- segmented(baseline_model_b2, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model_b2$psi[, "Est."]
      sse <- sum(residuals(segmented_model_b2)^2)
      tss <- sum((data_b2$log_Rate_fixed - mean(data_b2$log_Rate_fixed))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model_b2)
      bic <- calculate_bic(sse, num_obs, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_b2, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 4: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
