# Step 5: Create Plots for Each Model
plots_b2 <- list()

for (i in seq_along(segmented_model_b2)) {
  model_info_b2 <- segmented_model_b2[[i]]
  npsi <- comparison_b2$npsi[i]
  
  # Add fitted values to the data
  if (!is.null(model_info_b2$Model) && length(predict(model_info_b2$Model)) == nrow(data_b2)) {
    data_b2$Segmented_Fitted <- predict(model_info_b2$Model)
  }
  
  # Create joinpoint data only if joinpoints exist
  if (!is.null(model_info_b2$Joinpoints)) {
    joinpoint_data_b2 <- data.frame(
      Year = model_info_b2$Joinpoints,
      log_Rate_fixed = predict(model_info_b2$Model, newdata = data.frame(Year = model_info_b2$Joinpoints)),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data_b2 <- data.frame()
  }
  
  # Generate the Joinpoint Regression Plot
  incidence_plot_b2 <- ggplot(data_b2, aes(x = Year, y = Rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +  # Black dots
    geom_line(aes(y = exp(Segmented_Fitted) * 100, color = "Joinpoint Regression"), size = 1.2) +  # Blue line
    labs(
      title = paste("Joinpoint Model with", npsi, "Joinpoints"),
      subtitle = paste("BIC:", round(model_info_b2$BIC, 2), "| R²:", round(model_info_b2$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +  scale_color_manual(
      values = c("HIV Incidence" = "black", 
                 "Joinpoint Regression" = "blue",
                 "Breakpoints" = "red"),
      labels = c("HIV Incidence" = "Empirical incidence", 
                 "Joinpoint Regression" = "Model estimated incidence",
                 "Breakpoints" = "Breakpoints")) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(breaks = seq(min(data_b2$Year), max(data_b2$Year), by = 4)) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  # Add breakpoints (vertical lines) only if joinpoint_data is not empty
  if (nrow(joinpoint_data_b2) > 0) {
    incidence_plot_b2 <- incidence_plot_b2 +
      geom_vline(data = joinpoint_data_b2, aes(xintercept = Year), linetype = "dashed", color = "red", size = 1)
  }
  
  # Generate the APC Plot
  if (npsi == 0) {
    # For npsi = 0 (no breakpoints)
    coefs <- coef(model_info_b2$Model)
    se <- sqrt(diag(vcov(model_info_b2$Model)))
    
    # Define slope and standard error for the single segment
    slope <- coefs["Year"]
    se_blope <- se["Year"]
    
    # Calculate APC and 95% CI
    APC_b2 <- (exp(slope) - 1) * 100
    lower_CI_b2 <- (exp(slope - 1.96 * se_blope) - 1) * 100
    upper_CI_b2 <- (exp(slope + 1.96 * se_blope) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_b2 <- data.frame(
