                            2 * vcov(model_info_b2$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
      if (npsi >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                            2 * vcov(model_info_b2$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U3.Year"]), # SE for slope between the third and fourth breakpoints
      if (npsi >= 4) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + se["U4.Year"]^2 + 
