                            2 * vcov(model_info_b2$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["U3.Year", "U4.Year"]), 
      if (npsi >= 5) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + se["U4.Year"]^2 + se["U5.Year"]^2 +
                            2 * vcov(model_info_b2$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["Year", "U5.Year"] +
                            2 * vcov(model_info_b2$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U1.Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U3.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U4.Year"] + 
                            2 * vcov(model_info_b2$Model)["U2.Year", "U5.Year"] + 
                            2 * vcov(model_info_b2$Model)["U3.Year", "U4.Year"] +
                            2 * vcov(model_info_b2$Model)["U3.Year", "U5.Year"] +
                            2 * vcov(model_info_b2$Model)["U4.Year", "U5.Year"])
      
    )
    
    # Calculate APC and 95% CI for each segment
    APC_b2 <- (exp(slopes) - 1) * 100
    lower_CI_b2 <- (exp(slopes - 1.96 * se_blopes) - 1) * 100
    upper_CI_b2 <- (exp(slopes + 1.96 * se_blopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_b2 <- data.frame(
      Segment = paste("Segment", 1:length(slopes)),
      APC = APC_b2,
      LowerCI = lower_CI_b2,
      UpperCI = upper_CI_b2,
      Start_Year = c(min(data_b2$Year), model_info_b2$Joinpoints)[1:length(slopes)],
