# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)

# Function to manually compute BIC
calculate_bic_k <- function(sse, num_obs, num_joinpoints) {
  num_barams <- 2 * (num_joinpoints + 1)  # Parameters for slopes and intercepts
  bic <- log(sse / num_obs) + (num_barams / num_obs) * log(num_obs)
  return(bic)
}

# Step 1: Fit a Baseline Linear Model
baseline_model_k <- lm(rate ~ Year, data = hiv_trends_k)

# Step 2: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints <- 5  # Set the maximum number of joinpoints to test
num_obs <- nrow(hiv_trends_k)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_k)^2)
    tss <- sum((hiv_trends_k$rate - mean(hiv_trends_k$rate))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model_k)
    bic <- calculate_bic(sse, num_obs, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_k, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model_k <- segmented(baseline_model_k, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model_k$psi[, "Est."]
      sse <- sum(residuals(segmented_model_k)^2)
      tss <- sum((hiv_trends_k$rate - mean(hiv_trends_k$rate))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model_k)
      bic <- calculate_bic_k(sse, num_obs, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_k, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 3: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
segmented_model_k <- Filter(function(x) !is.null(x$AIC) && !is.null(x$BIC), results)
comparison_k <- data.frame(
  npsi = seq_along(segmented_model_k) - 1,
  AIC = sapply(segmented_model_k, function(x) x$AIC),
  BIC = sapply(segmented_model_k, function(x) x$BIC),
  RSS = sapply(segmented_model_k, function(x) x$RSS),
  R2 = sapply(segmented_model_k, function(x) x$R2),
  RMSE = sapply(segmented_model_k, function(x) x$RMSE)
)
print("Model Comparison (AIC, BIC, R2, and RMSE):")
print(comparison_k)
