# Step 3: Test Models with Limited Joinpoints (Dynamic npsi Selection)
max_joinpoints <- 3  # Set the maximum number of joinpoints to test
num_obs <- nrow(data_k)  # Number of observations
results <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_k)^2)
    tss <- sum((data_k$log_Rate - mean(data_k$log_Rate_fixed))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model_k)
    bic <- calculate_bic_k(sse, num_obs, npsi)
    results[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_k, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model_k <- segmented(baseline_model_k, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model_k$psi[, "Est."]
      sse <- sum(residuals(segmented_model_k)^2)
      tss <- sum((data_k$log_Rate_fixed - mean(data_k$log_Rate_fixed))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model_k)
      bic <- calculate_bic(sse, num_obs, npsi)
      results[[paste0("npsi_", npsi)]] <- list(Model = segmented_model_k, AIC = aic, BIC = bic, RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Step 4: Filter and Compare Models Using AIC, BIC, R^2, and RMSE
segmented_model_k <- Filter(function(x) !is.null(x$AIC) && !is.null(x$BIC), results)
comparison_k <- data.frame(
