# Step 5: Create Plots for Each Model
plots_k <- list()

for (i in seq_along(segmented_model_k)) {
  model_info_k <- segmented_model_k[[i]]
  npsi <- comparison_k$npsi[i]
  
  # Add fitted values to the data
  if (!is.null(model_info_k$Model) && length(predict(model_info_k$Model)) == nrow(data_k)) {
    data_k$Segmented_Fitted <- predict(model_info_k$Model)
  }
  
  # Create joinpoint data only if joinpoints exist
  if (!is.null(model_info_k$Joinpoints)) {
    joinpoint_data_k <- data.frame(
      Year = model_info_k$Joinpoints,
      log_Rate_fixed = predict(model_info_k$Model, newdata = data.frame(Year = model_info_k$Joinpoints)),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data_k <- data.frame()
  }
  
  # Generate the Joinpoint Regression Plot
  incidence_plot_k <- ggplot(data_k, aes(x = Year, y = Rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +  # Black dots
    geom_line(aes(y = exp(Segmented_Fitted) * 100, color = "Joinpoint Regression"), size = 1.2) +  # Blue line
    labs(
      title = paste("Joinpoint Model with", npsi, "Joinpoints"),
      subtitle = paste("BIC:", round(model_info_k$BIC, 2), "| R²:", round(model_info_k$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +  scale_color_manual(
      values = c("HIV Incidence" = "black", 
                 "Joinpoint Regression" = "blue",
                 "Breakpoints" = "red"),
      labels = c("HIV Incidence" = "Empirical incidence", 
                 "Joinpoint Regression" = "Model estimated incidence",
                 "Breakpoints" = "Breakpoints")) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(breaks = seq(min(data_k$Year), max(data_k$Year), by = 4)) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  # Add breakpoints (vertical lines) only if joinpoint_data is not empty
  if (nrow(joinpoint_data_k) > 0) {
    incidence_plot_k <- incidence_plot_k +
      geom_vline(data = joinpoint_data_k, aes(xintercept = Year), linetype = "dashed", color = "red", size = 1)
  }
  
  # Generate the APC Plot
  if (npsi == 0) {
    # For npsi = 0 (no breakpoints)
    coefs <- coef(model_info_k$Model)
    se <- sqrt(diag(vcov(model_info_k$Model)))
    
    # Define slope and standard error for the single segment
    slope <- coefs["Year"]
    se_blope <- se["Year"]
    
    # Calculate APC and 95% CI
    APC_k <- (exp(slope) - 1) * 100
    lower_CI_k <- (exp(slope - 1.96 * se_blope) - 1) * 100
    upper_CI_k <- (exp(slope + 1.96 * se_blope) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_k <- data.frame(
      Segment = "Overall",
      APC = APC_k,
      LowerCI = lower_CI_k,
      UpperCI = upper_CI_k,
      Start_Year = min(data_k$Year),
      End_Year = max(data_k$Year),
      Midpoint_Year = (min(data_k$Year) + max(data_k$Year)) / 2
    )
    
    # Create a formatted subtitle for APC
    apc_subtitle_k <- paste0(
      "Overall APC:  ", round(apc_data_k$APC, 2), "; 95% CI: (", 
      round(apc_data_k$LowerCI, 2), ", ", round(apc_data_k$UpperCI, 2), ")"
    )
    
    # Create the APC plot
    apc_plot_k <- ggplot(apc_data_k, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for the single segment
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +  # Point at the midpoint of the segment
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence interval
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      scale_x_continuous(breaks = seq(min(data_k$Year), max(data_k$Year), by = 4), limits = c(min(data_k$Year), max(data_k$Year))) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) \nin HIV Incidence with 95% CI",
        subtitle = apc_subtitle_k,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(model_info_k$Joinpoints)) {
    # For npsi >= 1 (with breakpoints)
    coefs <- coef(model_info_k$Model)
    se <- sqrt(diag(vcov(model_info_k$Model)))
    
    # Define slopes for each segment
    slopes <- c(
      coefs["Year"], # Slope before the first breakpoint
      if (npsi >= 1) coefs["Year"] + coefs["U1.Year"], # Slope between the first and second breakpoints
      if (npsi >= 2) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"], # Slope between the second and third breakpoints
      if (npsi >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"],  # Slope after the third breakpoint
      if (npsi >= 4) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"]  + coefs["U4.Year"], # Slope after the fourth breakpoint
      if (npsi >= 5) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"]  + coefs["U4.Year"] + coefs["U4.Year"] # Slope after the fourth breakpoint
    )
    
    # Define standard errors for each segment
    se_blopes <- c(
      se["Year"], # SE for slope before the first breakpoint
      if (npsi >= 1) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(model_info_k$Model)["Year", "U1.Year"]), # SE for slope between the first and second breakpoints
      if (npsi >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                            2 * vcov(model_info_k$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U2.Year"]), # SE for slope between the second and third breakpoints
      if (npsi >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                            2 * vcov(model_info_k$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U3.Year"]), # SE for slope between the third and fourth breakpoints
      if (npsi >= 4) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + se["U4.Year"]^2 + 
                            2 * vcov(model_info_k$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["U3.Year", "U4.Year"]), 
      if (npsi >= 5) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + se["U4.Year"]^2 + se["U5.Year"]^2 +
                            2 * vcov(model_info_k$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["Year", "U5.Year"] +
                            2 * vcov(model_info_k$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U1.Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U3.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U4.Year"] + 
                            2 * vcov(model_info_k$Model)["U2.Year", "U5.Year"] + 
                            2 * vcov(model_info_k$Model)["U3.Year", "U4.Year"] +
                            2 * vcov(model_info_k$Model)["U3.Year", "U5.Year"] +
                            2 * vcov(model_info_k$Model)["U4.Year", "U5.Year"])
      
    )
    
    # Calculate APC and 95% CI for each segment
    APC_k <- (exp(slopes) - 1) * 100
    lower_CI_k <- (exp(slopes - 1.96 * se_blopes) - 1) * 100
    upper_CI_k <- (exp(slopes + 1.96 * se_blopes) - 1) * 100
    
    # Create a data frame to store the results
    apc_data_k <- data.frame(
      Segment = paste("Segment", 1:length(slopes)),
      APC = APC_k,
      LowerCI = lower_CI_k,
      UpperCI = upper_CI_k,
      Start_Year = c(min(data_k$Year), model_info_k$Joinpoints)[1:length(slopes)],
      End_Year = c(model_info_k$Joinpoints, max(data_k$Year))[1:length(slopes)]
    )
    
    # Create a formatted subtitle with each segment on a separate line
    apc_subtitle_k <- paste0(
      "APC for Segment 1:  ", round(apc_data_k$APC[1], 2), "; 95% CI: (", 
      round(apc_data_k$LowerCI[1], 2), ", ", round(apc_data_k$UpperCI[1], 2), ")\n",
      if (npsi >= 1) paste0("APC for Segment 2:  ", round(apc_data_k$APC[2], 2), "; 95% CI: (", 
                            round(apc_data_k$LowerCI[2], 2), ", ", round(apc_data_k$UpperCI[2], 2), ")\n"),
      if (npsi >= 2) paste0("APC for Segment 3:  ", round(apc_data_k$APC[3], 2), "; 95% CI: (", 
                            round(apc_data_k$LowerCI[3], 2), ", ", round(apc_data_k$UpperCI[3], 2), ")\n"),
      if (npsi >= 3) paste0("APC for Segment 4:  ", round(apc_data_k$APC[4], 2), "; 95% CI: (", 
                            round(apc_data_k$LowerCI[4], 2), ", ", round(apc_data_k$UpperCI[4], 2), ")\n"),
      if (npsi >= 4) paste0("APC for Segment 5:  ", round(apc_data_k$APC[5], 2), "; 95% CI: (", 
                            round(apc_data_k$LowerCI[5], 2), ", ", round(apc_data_k$UpperCI[5], 2), ")\n"),
      if (npsi >= 5) paste0("APC for Segment 6:  ", round(apc_data$APC[6], 2), "; 95% CI: (", 
                            round(apc_data_k$LowerCI[6], 2), ", ", round(apc_data_k$UpperCI[6], 2), ")")
    )
    
    # Create the APC plot
    apc_plot_k <- ggplot(apc_data_k, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +  # Continuous line for each segment
      geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +  # Points at midpoints of each segment
      geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +  # Confidence intervals
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +  # Reference line at 0
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +  # Shaded confidence region
      geom_vline(xintercept = model_info_k$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +  # Vertical lines for breakpoints
      scale_x_continuous(breaks = seq(min(data_k$Year), max(data_k$Year), by = 4)) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +  # Format as percentages
      labs(
        title = "Annual Percentage Change (APC) \nin HIV Incidence with 95% CI",
        subtitle = apc_subtitle_k,  # Using the formatted subtitle
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )+
      scale_fill_discrete(name = " Time Segments ") +
      scale_color_discrete(name = " Time Segments ")
  } else {
    apc_plot_k <- NULL  # No APC plot for npsi = 0
  }
  
  # Combine the Joinpoint Regression Plot and APC Plot
