# Create survival probability data frame (inverted from risk)
surv_df <- data.frame(
  Time = risk_estimates$time,
  Survival = risk_estimates$surv,  # Probability of remaining HIV-free
  Lower = risk_estimates$lower,
  Upper = risk_estimates$upper
)
surv_df

# Plot with your preferred style - now showing survival
p_surv<-ggplot(surv_df, aes(x = Time, y = Survival)) +
  geom_point(size = 3, color = "darkred") + 
  geom_ribbon(aes(ymin = Lower, ymax = Upper), 
              fill = "lightgrey",        # Controls the fill color
              color = NA,               # Removes border line
              alpha = 0.5) +            # Makes it semi-transparent
  geom_line(color = "red", 
            linetype = "dashed", 
            linewidth = 0.8) +          # Fixed alpha issue (use linewidth instead)
  scale_x_continuous(breaks = seq(0, 13, 1), 
                     minor_breaks = NULL) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1),
                     limits = c(0.5, 0.85),
                     expand = c(0, 0)) +
  labs(x = "Follow-up (Years)", 
       y = "HIV acquisition risk (95% CI)",
       caption = "*Note: Data from last follow-up year is incomplete") +
  theme_classic() +
  theme(
    axis.title = element_text(face = "bold"),
    plot.caption = element_text(hjust = 0, face = "italic"),
    axis.line = element_line(linewidth = 0.8),
    axis.ticks = element_line(linewidth = 0.8)
  )

p_surv


