  Time = risk_estimates$time,
  N = risk_estimates$n.risk
)

risk_table_data

p_risk_table <- ggplot(risk_table_data, aes(x = Time, y = 1)) +
  geom_text(aes(label = format(N, big.mark = ",")), size = 4) +
  scale_x_continuous(breaks = seq(0, 12, 1)) +
  labs(x = NULL, y = "Number at risk") +
  theme_bw() +
  theme(
    text = element_text(size = 12),
    axis.text.y = element_blank(),
    axis.ticks.y = element_blank(),
    panel.grid = element_blank(),
    panel.border = element_blank(),
    axis.line.x = element_line()
  )

# 3. Cumulative events table
cum_events_data <- data.frame(
  Time = risk_estimates$time,
  Events = cumsum(risk_estimates$n.event)
)
cum_events_data
p_cum_events <- ggplot(cum_events_data, aes(x = Time, y = 1)) +
  geom_text(aes(label = format(Events, big.mark = ",")), size = 4) +
  scale_x_continuous(breaks = seq(0, 12, 1)) +
  labs(x = NULL, y = "Cumulative events") +
  theme_bw() +
  theme(
    text = element_text(size = 12),
    axis.text.y = element_blank(),
    axis.ticks.y = element_blank(),
    panel.grid = element_blank(),
    panel.border = element_blank(),
    axis.line.x = element_line()
  )

library(patchwork)
# 4. Combine all components
final_plot <- p_surv / p_risk_table / p_cum_events + 
  plot_layout(heights = c(3, 0.5, 0.5)) +
  plot_annotation(
    caption = "*Note: Data from last follow-up year is incomplete",
    theme = theme(
      plot.caption = element_text(hjust = 0, face = "italic", size = 12)
    )
  )

print(final_plot)


