combined_summary_HIV_overall <- tbl_summary(
  data = incidence_wide,
  include = c(
    Age_new, AgeStartedTakingDrugs, duraion_injection, duration_drug_use, 
    EducationYears, FrequencyOfDailyInjecting, TotalContacts, TotalSyringes,
    Organization_Name, Location, PWID_year, new_test_year, Province, Sex, 
    new_agegroup, starting_drug_agegroup_new, education_cat, MaritalStatus2, 
    source_income, recent_inj_freq, reason_initiate_inj_new, su_last_inj_new2, 
    new_inj_risk, new_new_inj_risk, place_inject_new, inj_street_doc, 
    freq_injection_new, ever_drug_use_new, recent_drug_use_new, con_use_last_si, 
    ever_jailed4drug, recent_jailed4drug, recent_inj_street_doc, duraion_injection_quartile,
    LiveOnStreetsAtNight, history_disease, selling_blood
  ),
  by = HIV,
  missing_text = "Missing",
  type = list(
    all_continuous() ~ "continuous2",
    all_categorical() ~ "categorical",
    all_dichotomous() ~ "categorical"
  ),
  statistic = list(
    all_continuous() ~ c("{mean} ({sd})", "{median} ({p25}–{p75})", "{min}–{max}"),
    all_categorical() ~ "{n} ({p}%)"
  ),
  digits = list(all_continuous() ~ c(1, 1), all_categorical() ~ c(0, 1)),
  label = list(
    Age_new ~ "Age",
    AgeStartedTakingDrugs ~ "Age of starting drug", 
    duraion_injection ~ "Duration of drug injection (years)",
    duration_drug_use ~ "Duration of any drug use (years)", 
    EducationYears ~ "Education years",
    FrequencyOfDailyInjecting ~ "Injection frequency",
    TotalContacts ~ "Total contacts since enrolment",
    TotalSyringes ~ "Total syringes received since enrolment",
    Organization_Name ~ "Name of harm reduction organization",
    Location ~ "Location settings",
    PWID_year ~ "Recruitment year",
    new_test_year ~ "New test year group",
    Province ~ "Province", 
    Sex ~ "Sex",
    new_agegroup ~ "New age group",
    starting_drug_agegroup_new ~ "Age group of starting drug use", 
    education_cat ~ "Education status", 
    MaritalStatus2 ~ "Marital status",
    source_income ~ "Source of income", 
    recent_inj_freq ~ "Recent injection frequency", 
    reason_initiate_inj_new ~ "Reason for initiating injection", 
    su_last_inj_new2 ~ "Recent syringe use behaviour", 
    new_inj_risk ~ "New injection risk", 
    new_new_inj_risk ~ "New (other) injection risk",
    place_inject_new ~ "Place of injection", 
    inj_street_doc ~ "Injection pushed by street doctor",
    freq_injection_new ~ "New frequency of injection",
    ever_drug_use_new ~ "Most commonly used injection drug", 
    recent_drug_use_new ~ "Recently used injection drug", 
    con_use_last_si ~ "Condom use last sex", 
    ever_jailed4drug ~ "Ever jailed for drug use", 
    recent_jailed4drug ~ "Recently jailed for drug use", 
    LiveOnStreetsAtNight ~ "Homelessness", 
    history_disease ~ "History of disease", 
    selling_blood ~ "Selling blood"
  )
) %>%
  add_overall(last = FALSE) %>%   
  add_n() %>%
  add_p() %>%
  modify_header(
    label = '**Variable**',
    stat_0 = '**Overall**',         # overall column
    stat_1 = '**HIV negative**',
    stat_2 = '**HIV positive**',
    p.value = '**p-value**'
  )



