)

############################################################
# 10. POOL RESULTS
############################################################

####
# Pool results
i.c_imp_pooled <- pool(i.c_imp)

# Get summary WITHOUT exponentiation
i.c_imp_pooled_summary <- summary(i.c_imp_pooled)

# Create results table (manually compute HR + CI)
# Use column indexing if you know the column positions
# Assuming column 1 is term, column 2 is estimate, column 3 is std.error, column 4 is p.value
# Convert to data frame (keeping row names as a column)
i.c_imp_pooled_summary_df <- as.data.frame(i.c_imp_pooled_summary)

# Add row names as a variable
i.c_imp_pooled_summary_df$Variable <- rownames(i.c_imp_pooled_summary_df)

# Clean up the variable names (remove the "relevel..." part)
i.c_imp_pooled_summary_df$Variable <- gsub("relevel\\(manuscript_education_cat, ref = \"College or more\"\\)", 
                                           "", 
                                           i.c_imp_pooled_summary_df$Variable)

# Create the summary data frame
i.c_imp_pooled_summary_ml <- data.frame(
  Variable = i.c_imp_pooled_summary_df$Variable,
  HR = exp(i.c_imp_pooled_summary_df$est),
  CI_lower = exp(i.c_imp_pooled_summary_df$est - 1.96 * i.c_imp_pooled_summary_df$se),
  CI_upper = exp(i.c_imp_pooled_summary_df$est + 1.96 * i.c_imp_pooled_summary_df$se),
  p_value = i.c_imp_pooled_summary_df$`Pr(>|t|)`
)

# View the result
print(i.c_imp_pooled_summary_ml)
# Check
head(i.c_imp_pooled_summary_ml)
head(i.c_imp_pooled_summary_ml)
# Format the table for publication
library(gt)

i.c_imp_pooled_summary_ml %>%
  mutate(
    CI = paste0("(", sprintf("%.2f", CI_lower), " - ", sprintf("%.2f", CI_upper), ")"),
    HR = sprintf("%.2f", HR),
    p_value = ifelse(p_value < 0.001, "<0.001", sprintf("%.3f", p_value))
  ) %>%
  select(Variable, HR, CI, p_value) %>%
  gt() %>%
  tab_header(
    title = "Multiple Imputation Results",
    subtitle = "Pooled across 20 imputed datasets (Rubin's Rules)"
  ) %>%
  cols_label(
    Variable = "Characteristic",
    HR = "Hazard Ratio",
    CI = "95% Confidence Interval",
    p_value = "P-value"
  ) %>%
  fmt_missing(columns = everything(), missing_text = "") %>%
  tab_style(
    style = cell_text(weight = "bold"),
    locations = cells_column_labels()
  )



