####

i.cc<- coxph(Surv(START, STOP, LEAD_HIV) ~ education_cat + 
               relevel(as.factor(new_agegroup), ref = "40+") + 
               relevel(as.factor(Sex), ref = "Male") + 
               relevel(as.factor(MaritalStatus2), ref = "Married") +
               source_income + 
               recent_homelessness + 
               recent_incarceration +
               new_test_year +
               City_Name  +
               Visits,
             data= incidence , 
             cluster = RegNo)%>%
  tbl_regression( exponentiate = TRUE,
                  add_estimate_to_reference_rows = TRUE,
                  label =list()) %>%
  modify_table_styling(
    columns = ci,
    rows = reference_row %in% TRUE,
    missing_symbol = "Ref."
  ) %>%
  bold_labels()
