incidence2<- subset(incidence_test, Visits < 4)
plyr::count(incidence2$Visits)



Pak_dat_short2_province <- incidence2 %>%
  group_by(ID,Province) %>%
  summarise(
    Study_entry = min(Date_corrected),
    Study_exit = max(Date_corrected),
    Status = last(Status)
  )




Pak_dat_short2_province$Study_entry2 <- as.Date(Pak_dat_short2_province$Study_entry)
Pak_dat_short2_province$Study_exit2 <- as.Date(Pak_dat_short2_province$Study_exit)
Pak_dat_short2_province$total_FUP <- Pak_dat_short2_province$Study_exit2 - Pak_dat_short2_province$Study_entry2  

min(Pak_dat_short2_province$total_FUP)


Pak_dat_short2_province$total_FUP_0 <- ifelse(Pak_dat_short2_province$total_FUP == 0, 1, 0)
table(Pak_dat_short2_province$total_FUP_0)

subset_data2_province <- subset(Pak_dat_short2_province, total_FUP == 0)



####Creating lexis durataion with Epi package in R

lex_split_Pak_dat2_province<- Epi::Lexis(
  entry = list(year = Study_entry2),
  exit  = list(year = Study_exit2),
  data = mutate_if(Pak_dat_short2_province, lubridate::is.Date, Epi::cal.yr)
)



# Split observations into follow-up periods
lex_split_Pak_dat2_province <- lex_split_Pak_dat2_province %>% 
  Epi::splitLexis(time.scale = "year", breaks = 2012 + 0:11)




# Correct HIV status because now we have the last status applied throughout
lex_split_Pak_dat2_province <- lex_split_Pak_dat2_province %>%
  group_by(ID,Province) %>%
  mutate(last_visit = ifelse(row_number() == n(), 1, 0))

lex_split_Pak_dat2_province

table(lex_split_Pak_dat2_province$Status)
lex_split_Pak_dat2_province$final_status <- ifelse(lex_split_Pak_dat2_province$last_visit == 0, 'Negative', lex_split_Pak_dat2_province$Status)
table(lex_split_Pak_dat2_province$final_status) # 10878 incident cases, right?






lex_split_Pak_dat2_province$final_status_num <- ifelse(lex_split_Pak_dat2_province$final_status == "Positive", 1, 0)
table(lex_split_Pak_dat2_province$final_status_num) # 10878 incident cases, right?

lex_split_Pak_dat2_province$lex.dur


lex_split_Pak_dat2_province$Time<-floor(lex_split_Pak_dat2_province$year)

lex_split_Pak_dat2_province


plyr::count(lex_split_Pak_dat2_province$Status)



incidence_data_prepared_province2_all <- survRate(Surv(lex.dur, final_status_num ) ~ Province,
                                                  data= lex_split_Pak_dat2_province, ) %>%
  dplyr::select(Province, event, tstop, rate, lower, upper) %>%
  as_tibble() %>%
  dplyr::rename(Province = Province,
                Events = event,
                Time= tstop,
                Rate = rate,
                'LowerCI'=lower,
                'UpperCI'= upper)



incidence_data_prepared_province2_all


