# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)
library(gridExtra)
library(grid)
##################### Trend analysis with restricting cities with 10 years and follow-up visits to three visits##############


inc_rate_restricted_follow_up2 <- data

inc_rate_restricted_follow_up2
inc_rate_restricted_follow_up<- subset(inc_rate_restricted_follow_up2, Visits < 4)
plyr::count(inc_rate_restricted_follow_up$Visits)





inc_rate_punjab_restricted_follow_up<-subset(inc_rate_restricted_follow_up, Province=="Punjab")
inc_rate_sindh_restricted_follow_up<-subset(inc_rate_restricted_follow_up, Province=="Sindh")
inc_rate_balochistan_restricted_follow_up<-subset(inc_rate_restricted_follow_up, Province=="Balochistan")



### finding cities with duration of follow-up years
calculate_followup_restricted_follow_up <- function(inc_rate_restricted_follow_up) {
  inc_rate %>%
    group_by(Province, City_Name, RegNo) %>%
    summarise(
      followup_period = max(Year) - min(Year),
      .groups = "drop"
    ) %>%
    group_by(City_Name) %>%
    summarise(
      longest_followup = max(followup_period),
      .groups = "drop"
    ) %>%
    arrange(desc(longest_followup))  # Sort cities by longest follow-up period
}

punjab_longest_restricted_follow_up <- calculate_followup(inc_rate_punjab_restricted_follow_up)
sindh_longest_restricted_follow_up <- calculate_followup(inc_rate_sindh_restricted_follow_up)
balochistan_longest_restricted_follow_up <- calculate_followup(inc_rate_balochistan_restricted_follow_up)


