###########################################
########Annual percentage change (APC) analysis for PSB##########
###########################################

# Load required libraries
library(segmented)
library(ggplot2)
library(dplyr)
library(ggpubr)
library(patchwork)
library(gridExtra)
library(grid)

# Prepare PSB data
hiv_trends2 <- incidence_rate_prepared_inc_rate_restricted_follow_up

# Convert Year to numeric
hiv_trends2$Year <- as.numeric(as.character(hiv_trends2$Year))
hiv_trends2$rate <- hiv_trends2$Rate

# Sort by Year
hiv_trends2 <- hiv_trends2 %>% arrange(Year)

# Function to manually compute BIC
calculate_bic <- function(sse, num_obs, num_joinpoints) {
  num_params <- 2 * (num_joinpoints + 1)
  bic <- log(sse / num_obs) + (num_params / num_obs) * log(num_obs)
  return(bic)
}

###########################################
# Part 1: Model Selection with Log-transformed Rates
###########################################

# Log-transform the Rate column
data_restricted_fu <- hiv_trends2 %>%
  mutate(log_Rate = log(Rate))

# Fit Baseline Linear Model
baseline_model_restricted_fu <- lm(log_Rate ~ Year, data = data_restricted_fu)

# Test Models with Limited Joinpoints
max_joinpoints <- min(3, floor(nrow(data_restricted_fu)/4))
num_obs <- nrow(data_restricted_fu)
results_restricted_fu <- list()

for (npsi in 0:max_joinpoints) {
  if (npsi == 0) {
    sse <- sum(residuals(baseline_model_restricted_fu)^2)
    tss <- sum((data_restricted_fu$log_Rate - mean(data_restricted_fu$log_Rate))^2)
    r2 <- 1 - (sse / tss)
    rmse <- sqrt(sse / num_obs)
    aic <- AIC(baseline_model_restricted_fu)
    bic <- calculate_bic(sse, num_obs, npsi)
    results_restricted_fu[[paste0("npsi_", npsi)]] <- list(Model = baseline_model_restricted_fu, AIC = aic, BIC = bic, 
                                                           RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = NULL)
  } else {
    tryCatch({
      segmented_model <- segmented(baseline_model_restricted_fu, seg.Z = ~Year, npsi = npsi)
      joinpoints <- segmented_model$psi[, "Est."]
      sse <- sum(residuals(segmented_model)^2)
      tss <- sum((data_restricted_fu$log_Rate - mean(data_restricted_fu$log_Rate))^2)
      r2 <- 1 - (sse / tss)
      rmse <- sqrt(sse / num_obs)
      aic <- AIC(segmented_model)
      bic <- calculate_bic(sse, num_obs, npsi)
      results_restricted_fu[[paste0("npsi_", npsi)]] <- list(Model = segmented_model, AIC = aic, BIC = bic, 
                                                             RSS = sse, R2 = r2, RMSE = rmse, Joinpoints = joinpoints)
    }, error = function(e) {
      results_restricted_fu[[paste0("npsi_", npsi)]] <- list(Error = e$message)
    })
  }
}

# Filter and Compare Models
valid_results_restricted_fu <- Filter(function(x) !is.null(x$AIC) && !is.null(x$BIC), results_restricted_fu)
comparison_restricted_fu <- data.frame(
  npsi = seq_along(valid_results_restricted_fu) - 1,
  AIC = sapply(valid_results_restricted_fu, function(x) x$AIC),
  BIC = sapply(valid_results_restricted_fu, function(x) x$BIC),
  RSS = sapply(valid_results_restricted_fu, function(x) x$RSS),
  R2 = sapply(valid_results_restricted_fu, function(x) x$R2),
  RMSE = sapply(valid_results_restricted_fu, function(x) x$RMSE)
)

print("Model Comparison for PSB (AIC, BIC, R2, and RMSE):")
print(comparison_restricted_fu)

###########################################
# Part 2: Create Plots for Each Model (All Joinpoints)
###########################################

plots_restricted_fu <- list()

for (i in seq_along(valid_results_restricted_fu)) {
  model_info <- valid_results_restricted_fu[[i]]
  npsi <- comparison_restricted_fu$npsi[i]
  
  # Add fitted values to the data
  if (!is.null(model_info$Model) && length(predict(model_info$Model)) == nrow(data_restricted_fu)) {
    data_restricted_fu$Segmented_Fitted <- predict(model_info$Model)
  }
  
  # Create joinpoint data
  if (!is.null(model_info$Joinpoints)) {
    joinpoint_data <- data.frame(
      Year = model_info$Joinpoints,
      log_Rate = predict(model_info$Model, newdata = data.frame(Year = model_info$Joinpoints)),
      Label = "Breakpoints"
    )
  } else {
    joinpoint_data <- data.frame()
  }
  
  # Joinpoint Regression Plot
  incidence_plot <- ggplot(data_restricted_fu, aes(x = Year, y = Rate * 100)) +
    geom_point(aes(color = "HIV Incidence"), size = 2) +
    geom_line(aes(y = exp(Segmented_Fitted) * 100, color = "Joinpoint Regression"), size = 1.2) +
    labs(
      title = paste("Joinpoint Model with", npsi, "Joinpoints"),
      subtitle = paste("BIC:", round(model_info$BIC, 2), "| R²:", round(model_info$R2, 3)),
      x = "Year",
      y = "HIV Incidence Rate (per 100 person-years)",
      color = "Legend"
    ) +
    scale_color_manual(
      values = c("HIV Incidence" = "black", "Joinpoint Regression" = "blue", "Breakpoints" = "red"),
      labels = c("HIV Incidence" = "Emperical incidence", 
                 "Joinpoint Regression" = "Model estimated incidence",
                 "Breakpoints" = "Breakpoints")
    ) +
    theme_minimal(base_size = 14) +
    scale_x_continuous(breaks = seq(min(data_restricted_fu$Year), max(data_restricted_fu$Year), by = 4)) +
    theme(
      axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
      plot.title = element_text(size = 14, face = "bold"),
      plot.subtitle = element_text(size = 12),
      legend.position = "bottom"
    )
  
  if (nrow(joinpoint_data) > 0) {
    incidence_plot <- incidence_plot +
      geom_vline(data = joinpoint_data, aes(xintercept = Year), linetype = "dashed", color = "red", size = 1)
  }
  
  # APC Plot
  if (npsi == 0) {
    coefs <- coef(model_info$Model)
    se <- sqrt(diag(vcov(model_info$Model)))
    
    slope <- coefs["Year"]
    se_slope <- se["Year"]
    
    APC <- (exp(slope) - 1) * 100
    lower_CI <- (exp(slope - 1.96 * se_slope) - 1) * 100
    upper_CI <- (exp(slope + 1.96 * se_slope) - 1) * 100
    
    apc_data <- data.frame(
      Segment = "Overall",
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI,
      Start_Year = min(data_restricted_fu$Year),
      End_Year = max(data_restricted_fu$Year),
      Midpoint_Year = (min(data_restricted_fu$Year) + max(data_restricted_fu$Year)) / 2
    )
    
    apc_subtitle <- paste0(
      "Overall APC:  ", round(apc_data$APC, 2), "; 95% CI: (", 
      round(apc_data$LowerCI, 2), ", ", round(apc_data$UpperCI, 2), ")"
    )
    
    apc_plot <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +
      geom_point(aes(x = Midpoint_Year, y = APC), size = 3) +
      geom_errorbar(aes(x = Midpoint_Year, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +
      scale_x_continuous(breaks = seq(min(data_restricted_fu$Year), max(data_restricted_fu$Year), by = 4)) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else if (!is.null(model_info$Joinpoints)) {
    coefs <- coef(model_info$Model)
    se <- sqrt(diag(vcov(model_info$Model)))
    
    slopes <- c(
      coefs["Year"],
      if (npsi >= 1) coefs["Year"] + coefs["U1.Year"],
      if (npsi >= 2) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"],
      if (npsi >= 3) coefs["Year"] + coefs["U1.Year"] + coefs["U2.Year"] + coefs["U3.Year"]
    )
    
    se_slopes <- c(
      se["Year"],
      if (npsi >= 1) sqrt(se["Year"]^2 + se["U1.Year"]^2 + 2 * vcov(model_info$Model)["Year", "U1.Year"]),
      if (npsi >= 2) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + 
                            2 * vcov(model_info$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U2.Year"]),
      if (npsi >= 3) sqrt(se["Year"]^2 + se["U1.Year"]^2 + se["U2.Year"]^2 + se["U3.Year"]^2 + 
                            2 * vcov(model_info$Model)["Year", "U1.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["Year", "U3.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U2.Year"] + 
                            2 * vcov(model_info$Model)["U1.Year", "U3.Year"] + 
                            2 * vcov(model_info$Model)["U2.Year", "U3.Year"])
    )
    
    APC <- (exp(slopes) - 1) * 100
    lower_CI <- (exp(slopes - 1.96 * se_slopes) - 1) * 100
    upper_CI <- (exp(slopes + 1.96 * se_slopes) - 1) * 100
    
    apc_data <- data.frame(
      Segment = paste("Segment", 1:length(slopes)),
      APC = APC,
      LowerCI = lower_CI,
      UpperCI = upper_CI,
      Start_Year = c(min(data_restricted_fu$Year), model_info$Joinpoints)[1:length(slopes)],
      End_Year = c(model_info$Joinpoints, max(data_restricted_fu$Year))[1:length(slopes)]
    )
    
    apc_subtitle <- paste0(
      "APC for Segment 1:  ", round(apc_data$APC[1], 2), "; 95% CI: (", 
      round(apc_data$LowerCI[1], 2), ", ", round(apc_data$UpperCI[1], 2), ")\n",
      if (npsi >= 1) paste0("APC for Segment 2:  ", round(apc_data$APC[2], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[2], 2), ", ", round(apc_data$UpperCI[2], 2), ")\n"),
      if (npsi >= 2) paste0("APC for Segment 3:  ", round(apc_data$APC[3], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[3], 2), ", ", round(apc_data$UpperCI[3], 2), ")\n"),
      if (npsi >= 3) paste0("APC for Segment 4:  ", round(apc_data$APC[4], 2), "; 95% CI: (", 
                            round(apc_data$LowerCI[4], 2), ", ", round(apc_data$UpperCI[4], 2), ")")
    )
    
    apc_plot <- ggplot(apc_data, aes(x = Start_Year, y = APC, group = Segment, color = Segment)) +
      geom_line(size = 1.5) +
      geom_point(aes(x = (Start_Year + End_Year) / 2, y = APC), size = 3) +
      geom_errorbar(aes(x = (Start_Year + End_Year) / 2, ymin = LowerCI, ymax = UpperCI), width = 0.5, color = "black") +
      geom_hline(yintercept = 0, linetype = "dashed", color = "black") +
      geom_ribbon(aes(ymin = LowerCI, ymax = UpperCI, fill = Segment), alpha = 0.2) +
      geom_vline(xintercept = model_info$Joinpoints, linetype = "dashed", color = "red", size = 0.8) +
      scale_x_continuous(breaks = seq(min(data_restricted_fu$Year), max(data_restricted_fu$Year), by = 4)) +
      scale_y_continuous(labels = scales::percent_format(scale = 1)) +
      labs(
        title = "Annual Percentage Change (APC) in HIV Incidence with 95% CI",
        subtitle = apc_subtitle,
        x = "Year",
        y = "Annual Percentage Change (%)"
      ) +
      theme_minimal() +
      theme(
        axis.text.x = element_text(angle = 45, hjust = 1, size = 10),
        plot.title = element_text(size = 14, face = "bold"),
        plot.subtitle = element_text(size = 12),
        legend.position = "right"
      )
  } else {
    apc_plot <- NULL
  }
  
  # Combine plots
  if (!is.null(apc_plot)) {
    combined_plot <- incidence_plot + apc_plot + plot_layout(nrow = 1)
  } else {
    combined_plot <- incidence_plot
  }
  
  plots_restricted_fu[[i]] <- combined_plot
}

