# Create complete year template (2012-2024)
complete_years <- data.frame(Year = as.character(2012:2024))

# Start with complete years template, then add data
incidence_data_prepared_province_punjab_updated <- complete_years %>%
  left_join(incidence_data_prepared_province_punjab %>% 
              mutate(Year = as.character(Year)), by = "Year") %>%
  left_join(total_ids_per_year_punjab_updated, by = "Year")

incidence_data_prepared_province_punjab_updated


incidence_data_prepared_province_punjab_updated$Total_IDs<-incidence_data_prepared_province_punjab_updated$Total_IDs.x


# Fill missing Total_IDs with 0
incidence_data_prepared_province_punjab_updated$Total_IDs[is.na(incidence_data_prepared_province_punjab_updated$Total_IDs)] <- 0

# Reorder columns - place Total_IDs after Year
incidence_data_prepared_province_punjab_updated <- incidence_data_prepared_province_punjab_updated %>%
  relocate(Total_IDs, .after = Year)

# Convert Year to factor for plotting (with all levels 2012-2024)
incidence_data_prepared_province_punjab_updated$Year <- factor(incidence_data_prepared_province_punjab_updated$Year, 
                                                               levels = as.character(2012:2024))

# Plot
inc_plot_punjab_updated <- ggplot(data = incidence_data_prepared_province_punjab_updated, 
                                  aes(x = Year, y = Rate * 100, group = 1)) +
  geom_ribbon(aes(ymin = LowerCI * 100, ymax = UpperCI * 100), fill = "darkred", alpha = 0.25) +
  geom_point() + 
  geom_line(aes(group = 1)) + 
  xlab("Year") +
  ylab("\n\n\n\n\nIncidence estimate (per 100 person-years)") +
  expand_limits(y = 0) +  
  labs(title = "Punjab\n\n", caption = expression(paste(italic("*Note: Data for 2024 is incomplete")))) +
  scale_x_discrete(breaks = c("2012", "2014", "2016", "2018", "2020", "2022", "2024")) +
  theme(text = element_text(size = 14),
        axis.text = element_text(size = 14),
        axis.title = element_text(size = 14),
        plot.title = element_text(size = 14),
        legend.text = element_text(size = 14),
        legend.title = element_text(size = 14),
        axis.line = element_line(color = "black"),
        axis.ticks = element_line(color = "black"),
        strip.text = element_text(size = 14),
        panel.background = element_rect(fill = "white"),
        plot.background = element_rect(fill = "white"),
        panel.grid.major = element_line(color = "gray95", linewidth = 0.3),
        panel.grid.minor = element_line(color = "gray95", linewidth = 0.15))

# Create risk table with "-" for missing values
risk_table_Pak_dat_punjab_updated <- incidence_data_prepared_province_punjab_updated %>%
  select(Year, Total_IDs, Events, Time, Rate) %>%
  pivot_longer(cols = c(Total_IDs, Events, Time, Rate), names_to = "Metric", values_to = "Value") %>%
  mutate(Metric = case_when(
    Metric == "Total_IDs" ~ "People at Risk",
    Metric == "Events" ~ "Events",
    Metric == "Time" ~ "Person-Years",
    Metric == "Rate" ~ "HIV incidence (/100py)"
  ),
  Value = ifelse(Metric == "HIV incidence (/100py)" & !is.na(Value), round(Value * 100, 2), Value),
  Value = ifelse(is.na(Value), "-", as.character(Value))) %>%
  pivot_wider(names_from = Year, values_from = Value)

# Convert to matrix for tableGrob
metric_names_punjab_updated <- risk_table_Pak_dat_punjab_updated$Metric
risk_table_Pak_dat_punjab_updated <- as.matrix(risk_table_Pak_dat_punjab_updated[, -1])
rownames(risk_table_Pak_dat_punjab_updated) <- metric_names_punjab_updated

# Create tableGrob
table_grob_Pak_dat_punjab_updated <- tableGrob(
  risk_table_Pak_dat_punjab_updated,
  theme = ttheme_minimal(
    base_size = 10,
    core = list(
      bg_params = list(fill = "white", col = "black"),
      fg_params = list(hjust = 0, x = 0.1)
    ),
    rowhead = list(fg_params = list(fontface = "bold"))
  )
)

# Combine plot and table
final_plot_Pak_dat_punjab_updated <- grid.arrange(
  inc_plot_punjab_updated,
  table_grob_Pak_dat_punjab_updated,
  nrow = 2,
  heights = c(3.1, 1.2),
  widths = unit(.73, "npc")
)

print(final_plot_Pak_dat_punjab_updated)

ggsave(
  filename = "HIV Incidence_trend_risktable_punjab_updated.jpg",
  plot = final_plot_Pak_dat_punjab_updated,
  width = 10.7,
  height = 8,
  dpi = 300,
  device = "jpg"
)


